        public const string P305_INQUIRY_RESULTS = """
        select i."INQUIRY_ID", rt."INQUIRY_NAME_EN" "INQUIRY_TYPE", i."SUBJECT_TYPE", i."INQUIRY_DATE", i."REFERENCE_NO", i."RESULT_CODE", coalesce(rl."RISK_LEVEL_NAME_EN", i."RISK_LEVEL_CODE") "RISK_LEVEL"
        from "MTG_INQUIRY_RESULTS" i
        join "MTG_LKP_INQUIRY_TYPES" rt on rt."INQUIRY_TYPE_CODE" = i."INQUIRY_TYPE_CODE"
        left join "ADM_LKP_RISK_LEVELS" rl on rl."RISK_LEVEL_CODE" = i."RISK_LEVEL_CODE"
        where i."PORTFOLIO_ID" = @P305_PORTFOLIO_ID::bigint
        order by i."INQUIRY_DATE" desc, i."INQUIRY_ID" desc
        """;

        public const string P407_PORTFOLIO_CHEQUES = """
        select c."CHEQUE_ID", c."PORTFOLIO_ID", case when c."PORTFOLIO_ACCOUNT_ID" is null then 'Portfolio Level' else concat(i."INVESTOR_CODE", ' - ', coalesce(i."FULL_NAME_EN", '-'), ' - ', u."UNIT_CODE") end "ACCOUNT_NAME", c."CHEQUE_NO", c."BANK_NAME", c."CHEQUE_DATE", c."DUE_DATE", c."CHEQUE_AMOUNT", c."IS_ENDORSED_TO_COMPANY" AS "ENDORSED_TO_COMPANY_FLAG", cs."CHEQUE_STATUS_EN" "CHEQUE_STATUS", c."CLEARING_DATE", c."RETURN_REASON"
        from "MTG_PURCHASED_PORTFOLIO_CHEQUES" c
        left join "MTG_PURCHASED_PORTFOLIO_ACCOUNTS" pa on pa."PORTFOLIO_ACCOUNT_ID" = c."PORTFOLIO_ACCOUNT_ID"
        left join "MTG_INVESTORS" i on i."INVESTOR_ID" = pa."INVESTOR_ID"
        left join "MTG_PROJECT_UNITS" u on u."UNIT_ID" = pa."UNIT_ID"
        join "ADM_LKP_CHEQUE_STATUSES" cs on cs."CHEQUE_STATUS_CODE" = c."CHEQUE_STATUS_CODE"
        where c."PORTFOLIO_ID" = @P407_PORTFOLIO_ID::bigint
        order by c."DUE_DATE", c."CHEQUE_NO"
        """;

        public const string P46_PORTFOLIO_PROTECTION_COVERAGE_SUMMARY = """
        with g as (select "PORTFOLIO_ID", count(*) "GUARANTEE_COUNT", sum(coalesce("GUARANTEE_AMOUNT", 0)) "GUARANTEE_AMOUNT", sum(case when "IS_VERIFIED" then 1 else 0 end) "VERIFIED_GUARANTEE_COUNT", sum(case when "EXPIRY_DATE" between current_date and current_date + 30 then 1 else 0 end) "GUARANTEE_EXPIRING_30"
        from "MTG_GUARANTEES"
        group by "PORTFOLIO_ID"), ins as (select "PORTFOLIO_ID", count(*) "INSURANCE_COUNT", sum(coalesce("SUM_INSURED", 0)) "SUM_INSURED", sum(case when "IS_ASSIGNED_TO_COMPANY" then 1 else 0 end) "ASSIGNED_POLICY_COUNT", sum(case when "VALID_TO_DATE" between current_date and current_date + 30 then 1 else 0 end) "INSURANCE_EXPIRING_30"
        from "MTG_INSURANCES"
        group by "PORTFOLIO_ID"), dep as (select "PORTFOLIO_ID", count(*) "DEPOSIT_COUNT", sum(coalesce("DEPOSIT_AMOUNT", 0)) "DEPOSIT_AMOUNT", sum(case when "IS_BLOCKED" then coalesce("DEPOSIT_AMOUNT", 0) else 0 end) "BLOCKED_DEPOSIT_AMOUNT"
        from "MTG_SECURITY_DEPOSITS"
        group by "PORTFOLIO_ID"), base as (select p."PORTFOLIO_ID", p."PORTFOLIO_NO", p."DEVELOPER_ID", p."PROJECT_ID", d."LEGAL_NAME_EN" "DEVELOPER_NAME_EN", pr."PROJECT_NAME_EN", p."PROPOSED_PURCHASE_VALUE", coalesce(g."GUARANTEE_COUNT", 0) "GUARANTEE_COUNT", coalesce(g."GUARANTEE_AMOUNT", 0) "GUARANTEE_AMOUNT", coalesce(g."VERIFIED_GUARANTEE_COUNT", 0) "VERIFIED_GUARANTEE_COUNT", coalesce(g."GUARANTEE_EXPIRING_30", 0) "GUARANTEE_EXPIRING_30", coalesce(ins."INSURANCE_COUNT", 0) "INSURANCE_COUNT", coalesce(ins."SUM_INSURED", 0) "SUM_INSURED", coalesce(ins."ASSIGNED_POLICY_COUNT", 0) "ASSIGNED_POLICY_COUNT", coalesce(ins."INSURANCE_EXPIRING_30", 0) "INSURANCE_EXPIRING_30", coalesce(dep."DEPOSIT_COUNT", 0) "DEPOSIT_COUNT", coalesce(dep."DEPOSIT_AMOUNT", 0) "DEPOSIT_AMOUNT", coalesce(dep."BLOCKED_DEPOSIT_AMOUNT", 0) "BLOCKED_DEPOSIT_AMOUNT", round(100 * coalesce(g."GUARANTEE_AMOUNT", 0) / (nullif(p."PROPOSED_PURCHASE_VALUE", 0))::numeric, 2) "GUARANTEE_COVERAGE_PCT", round(100 * coalesce(dep."DEPOSIT_AMOUNT", 0) / (nullif(p."PROPOSED_PURCHASE_VALUE", 0))::numeric, 2) "DEPOSIT_COVERAGE_PCT"
        from "MTG_PURCHASED_PORTFOLIOS" p
        join "MTG_DEVELOPERS" d on d."DEVELOPER_ID" = p."DEVELOPER_ID"
        join "MTG_PROJECTS" pr on pr."PROJECT_ID" = p."PROJECT_ID"
        left join g on g."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        left join ins on ins."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        left join dep on dep."PORTFOLIO_ID" = p."PORTFOLIO_ID" where (@P744_PORTFOLIO_ID::bigint is null or p."PORTFOLIO_ID" = @P744_PORTFOLIO_ID::bigint) and (@P744_DEVELOPER_ID::bigint is null or p."DEVELOPER_ID" = @P744_DEVELOPER_ID::bigint) and (@P744_PROJECT_ID::bigint is null or p."PROJECT_ID" = @P744_PROJECT_ID::bigint)) select *
        from base where (coalesce(@P744_EXPIRY_RISK_ONLY::text, 'N') = 'N' or "GUARANTEE_EXPIRING_30" > 0 or "INSURANCE_EXPIRING_30" > 0)
        order by "PORTFOLIO_NO"
        """;

        public const string P501_GUARANTEES = """
        select g."GUARANTEE_ID", g."PORTFOLIO_ID", gt."GUARANTEE_NAME_EN" "GUARANTEE_TYPE", case gt."IS_MANDATORY" when 'Y' then 'Yes' else 'No' end "IS_MANDATORY", g."GUARANTOR_TYPE", g."GUARANTOR_ID", g."GUARANTEE_AMOUNT", g."GUARANTEE_PCT", g."EFFECTIVE_DATE", g."EXPIRY_DATE", case g."IS_VERIFIED" when 'Y' then 'Yes' else 'No' end "IS_VERIFIED", g."VERIFIED_BY", cast(g."VERIFIED_AT" as date) "VERIFIED_DATE", coalesce(d."DOCUMENT_NO", d."FILE_NAME") "DOCUMENT_REFERENCE"
        from "MTG_GUARANTEES" g
        join "ADM_LKP_GUARANTEE_TYPES" gt on gt."GUARANTEE_TYPE_CODE" = g."GUARANTEE_TYPE_CODE"
        left join "MTG_PURCHASED_PORTFOLIO_DOCUMENTS" d on d."DOCUMENT_ID" = g."DOCUMENT_ID"
        where g."PORTFOLIO_ID" = @P501_PORTFOLIO_ID::bigint
        order by gt."IS_MANDATORY" desc, gt."DISPLAY_SEQ", g."GUARANTEE_ID" desc
        """;

        public const string P503_INSURANCE = """
        select i."INSURANCE_ID", i."PORTFOLIO_ID", u."UNIT_CODE", t."INSURANCE_NAME_EN" "INSURANCE_TYPE", i."INSURANCE_COMPANY", i."POLICY_NO", i."SUM_INSURED", i."VALID_FROM_DATE" AS "VALID_FROM", i."VALID_TO_DATE" AS "VALID_TO", case i."IS_ASSIGNED_TO_COMPANY" when 'Y' then 'Yes' else 'No' end "IS_ASSIGNED_TO_COMPANY", coalesce(d."DOCUMENT_NO", d."FILE_NAME") "DOCUMENT_REFERENCE"
        from "MTG_INSURANCES" i
        join "ADM_LKP_INSURANCE_TYPES" t on t."INSURANCE_TYPE_CODE" = i."INSURANCE_TYPE_CODE"
        left join "MTG_PROJECT_UNITS" u on u."UNIT_ID" = i."UNIT_ID"
        left join "MTG_PURCHASED_PORTFOLIO_DOCUMENTS" d on d."DOCUMENT_ID" = i."DOCUMENT_ID"
        where i."PORTFOLIO_ID" = @P503_PORTFOLIO_ID::bigint
        order by i."VALID_TO_DATE" desc nulls last, i."INSURANCE_ID" desc
        """;

        public const string P505_SECURITY_DEPOSITS = """
        select s."DEPOSIT_ID", s."PORTFOLIO_ID", s."BANK_NAME", s."ACCOUNT_REFERENCE", s."DEPOSIT_AMOUNT", s."DEPOSIT_PCT", case s."IS_BLOCKED" when 'Y' then 'Yes' else 'No' end "IS_BLOCKED", s."START_DATE", s."RELEASE_DATE", coalesce(d."DOCUMENT_NO", d."FILE_NAME") "DOCUMENT_REFERENCE"
        from "MTG_SECURITY_DEPOSITS" s
        left join "MTG_PURCHASED_PORTFOLIO_DOCUMENTS" d on d."DOCUMENT_ID" = s."DOCUMENT_ID"
        where s."PORTFOLIO_ID" = @P505_PORTFOLIO_ID::bigint
        order by s."START_DATE" desc nulls last, s."DEPOSIT_ID" desc
        """;

        public const string P601_COMPREHENSIVE_MEMO = """
        select "MEMO_ID", "VERSION_NO", "MEMO_DATE", "MEMO_STATUS", "PREPARED_BY", "PREPARED_DATE", substr("EXECUTIVE_SUMMARY", 1, 300) "EXECUTIVE_SUMMARY_PREVIEW", substr("RECOMMENDATION", 1, 300) "RECOMMENDATION_PREVIEW"
        from "MTG_PURCHASED_PORTFOLIO_MEMOS"
        where "PORTFOLIO_ID" = @P601_PORTFOLIO_ID::bigint
        order by "VERSION_NO" desc
        """;

        public const string P606_APPROVAL_HISTORY = """
        select a."APPROVAL_ID", s."STEP_NAME_EN" "STEP_NAME", a."SEQUENCE_NO", a."ASSIGNED_TO", a."ASSIGNED_DATE", coalesce(d."DECISION_NAME_EN", 'Pending') "DECISION_NAME", a."DECISION_DATE", coalesce(rs."STEP_NAME_EN", '-') "RETURN_TO_STEP", substr(a."COMMENTS", 1, 500) "COMMENTS"
        from "MTG_PURCHASED_PORTFOLIO_APPROVALS" a
        join "MTG_LKP_APPROVAL_STEPS" s on s."STEP_CODE" = a."STEP_CODE"
        left join "ADM_LKP_DECISION_TYPES" d on d."DECISION_CODE" = a."DECISION_CODE"
        left join "MTG_LKP_APPROVAL_STEPS" rs on rs."STEP_CODE" = a."RETURN_TO_STEP_CODE"
        where a."PORTFOLIO_ID" = @P606_PORTFOLIO_ID::bigint
        order by a."APPROVAL_ID" desc
        """;

        public const string P607_STATUS_HISTORY = """
        select h."STATUS_HIST_ID", coalesce(fs."STATUS_NAME_EN", '-') "FROM_STATUS", ts."STATUS_NAME_EN" "TO_STATUS", cast(h."CHANGE_AT" as date) "CHANGE_DATE", h."CHANGED_BY", h."COMMENTS"
        from "MTG_PURCHASED_PORTFOLIO_STATUS_HIST" h
        left join "MTG_LKP_PORTFOLIO_STATUSES" fs on fs."STATUS_CODE" = h."FROM_STATUS"
        join "MTG_LKP_PORTFOLIO_STATUSES" ts on ts."STATUS_CODE" = h."TO_STATUS"
        where h."PORTFOLIO_ID" = @P607_PORTFOLIO_ID::bigint
        order by h."CHANGE_AT" desc
        """;

        public const string P701_OPERATIONAL_MONITORING = """
        with "FNV_V_CHEQUE_COVERAGE" AS (
        select pf."PORTFOLIO_ID", pf."PORTFOLIO_NO", pf."OUTSTANDING_VALUE", pf."EXPECTED_RETURN_AMOUNT", pf."OUTSTANDING_VALUE" + pf."EXPECTED_RETURN_AMOUNT" as "REQUIRED_COVERAGE_AMOUNT", coalesce(sum(c."CHEQUE_AMOUNT"), 0) as "CHEQUE_TOTAL_AMOUNT", case when (pf."OUTSTANDING_VALUE" + pf."EXPECTED_RETURN_AMOUNT") = 0 then null else round(coalesce(sum(c."CHEQUE_AMOUNT"), 0) / ((pf."OUTSTANDING_VALUE" + pf."EXPECTED_RETURN_AMOUNT"))::numeric * 100, 2) end as "CHEQUE_COVERAGE_PCT", case when coalesce(sum(c."CHEQUE_AMOUNT"), 0) >= (pf."OUTSTANDING_VALUE" + pf."EXPECTED_RETURN_AMOUNT") then 'Y' else 'N' end as "COVERAGE_OK_FLAG"
        from "MTG_PURCHASED_PORTFOLIOS" pf
        left join "MTG_PURCHASED_PORTFOLIO_CHEQUES" c on c."PORTFOLIO_ID" = pf."PORTFOLIO_ID"
        group by pf."PORTFOLIO_ID", pf."PORTFOLIO_NO", pf."OUTSTANDING_VALUE", pf."EXPECTED_RETURN_AMOUNT"
        ),
        "FNV_V_PAYMENT_REGULARITY" AS (
        select pa."PORTFOLIO_ACCOUNT_ID", pa."PORTFOLIO_ID", pa."INVESTOR_ID", i."INVESTOR_CODE", i."FULL_NAME_AR", i."FULL_NAME_EN", count(ap."PAYMENT_ID") as "PAYMENT_COUNT", sum(case when ap."PAYMENT_STATUS_CODE" = 'PAID' then 1 else 0 end) as "PAID_COUNT", sum(case when ap."PAYMENT_STATUS_CODE" = 'LATE' then 1 else 0 end) as "LATE_COUNT", sum(case when ap."PAYMENT_STATUS_CODE" in ('PARTIAL', 'UNPAID') then 1 else 0 end) as "PROBLEM_COUNT", max(ap."DAYS_LATE") as "MAX_DAYS_LATE", sum(ap."DUE_AMOUNT") as "TOTAL_DUE", sum(ap."PAID_AMOUNT") as "TOTAL_PAID"
        from "MTG_PURCHASED_PORTFOLIO_ACCOUNTS" pa
        join "MTG_INVESTORS" i on i."INVESTOR_ID" = pa."INVESTOR_ID"
        left join "MTG_ACCOUNT_PAYMENTS" ap on ap."PORTFOLIO_ACCOUNT_ID" = pa."PORTFOLIO_ACCOUNT_ID"
        group by pa."PORTFOLIO_ACCOUNT_ID", pa."PORTFOLIO_ID", pa."INVESTOR_ID", i."INVESTOR_CODE", i."FULL_NAME_AR", i."FULL_NAME_EN"
        ),
        "FNV_V_PORTFOLIO_EXCEPTIONS" AS (
        select p."PORTFOLIO_ID", p."PORTFOLIO_NO", 'DUE_DILIGENCE' "EXCEPTION_TYPE", dd."CHECK_TYPE_CODE" "EXCEPTION_CODE", dd."FINDINGS" "EXCEPTION_DETAILS"
        from "MTG_PURCHASED_PORTFOLIOS" p
        join "MTG_DUE_DILIGENCES" dd on dd."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        where dd."IS_EXCEPTION"
        union all select p."PORTFOLIO_ID", p."PORTFOLIO_NO", 'PAYMENT_HISTORY', 'PAYMENT_IRREGULARITY', (concat('Payment problems found for investor ', pr."FULL_NAME_EN"))
        from "MTG_PURCHASED_PORTFOLIOS" p
        join "FNV_V_PAYMENT_REGULARITY" pr on pr."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        where pr."PAYMENT_COUNT" < 12 or pr."PROBLEM_COUNT" > 0
        union all select p."PORTFOLIO_ID", p."PORTFOLIO_NO", 'CHEQUE_COVERAGE', 'INSUFFICIENT_COVERAGE', ('Cheque coverage is below required amount')
        from "MTG_PURCHASED_PORTFOLIOS" p
        join "FNV_V_CHEQUE_COVERAGE" cc on cc."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        where cc."COVERAGE_OK_FLAG" = 'N'
        ),
        "FNV_V_DOCUMENT_COMPLETENESS" AS (
        with req as (select count(*) "REQUIRED_COUNT"
        from "ADM_LKP_DOCUMENT_TYPES"
        where "IS_MANDATORY" and "IS_ACTIVE"), doc as (select "PORTFOLIO_ID", count(distinct "DOCUMENT_TYPE_CODE") "RECEIVED_REQUIRED_COUNT"
        from "MTG_PURCHASED_PORTFOLIO_DOCUMENTS" d
        where exists (select 1
        from "ADM_LKP_DOCUMENT_TYPES" r
        where r."DOCUMENT_TYPE_CODE" = d."DOCUMENT_TYPE_CODE" and r."IS_MANDATORY" and r."IS_ACTIVE")
        group by "PORTFOLIO_ID") select p."PORTFOLIO_ID", p."PORTFOLIO_NO", r."REQUIRED_COUNT", coalesce(d."RECEIVED_REQUIRED_COUNT", 0) "RECEIVED_REQUIRED_COUNT", greatest(r."REQUIRED_COUNT" - coalesce(d."RECEIVED_REQUIRED_COUNT", 0), 0) "MISSING_REQUIRED_COUNT", case when r."REQUIRED_COUNT" = 0 then 100 else round(coalesce(d."RECEIVED_REQUIRED_COUNT", 0) / (r."REQUIRED_COUNT")::numeric * 100, 2) end "DOCUMENT_COMPLETION_PCT", case when coalesce(d."RECEIVED_REQUIRED_COUNT", 0) >= r."REQUIRED_COUNT" then 'Y' else 'N' end "DOCUMENT_READY_FLAG"
        from "MTG_PURCHASED_PORTFOLIOS" p
        cross join req r
        left join doc d on d."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        ),
        "FNV_V_GUARANTEE_STATUS" AS (
        with req as (select count(*) "REQUIRED_COUNT"
        from "ADM_LKP_GUARANTEE_TYPES"
        where "IS_MANDATORY" and "IS_ACTIVE"), got as (select "PORTFOLIO_ID", count(distinct "GUARANTEE_TYPE_CODE") "VERIFIED_REQUIRED_COUNT"
        from "MTG_GUARANTEES" g
        where "IS_VERIFIED" and exists (select 1
        from "ADM_LKP_GUARANTEE_TYPES" r
        where r."GUARANTEE_TYPE_CODE" = g."GUARANTEE_TYPE_CODE" and r."IS_MANDATORY" and r."IS_ACTIVE")
        group by "PORTFOLIO_ID") select p."PORTFOLIO_ID", p."PORTFOLIO_NO", r."REQUIRED_COUNT", coalesce(g."VERIFIED_REQUIRED_COUNT", 0) "VERIFIED_REQUIRED_COUNT", greatest(r."REQUIRED_COUNT" - coalesce(g."VERIFIED_REQUIRED_COUNT", 0), 0) "MISSING_REQUIRED_COUNT", case when coalesce(g."VERIFIED_REQUIRED_COUNT", 0) >= r."REQUIRED_COUNT" then 'Y' else 'N' end "GUARANTEE_READY_FLAG"
        from "MTG_PURCHASED_PORTFOLIOS" p
        cross join req r
        left join got g on g."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        ),
        "FNV_V_LEGAL_STATUS" AS (
        select p."PORTFOLIO_ID", p."PORTFOLIO_NO", lr."LEGAL_REVIEW_ID", case when lr."IS_OWNERSHIP_VERIFIED" then 'Y' when not lr."IS_OWNERSHIP_VERIFIED" then 'N' end AS "OWNERSHIP_VERIFIED_FLAG", case when lr."IS_BUILDING_LICENSE_VERIFIED" then 'Y' when not lr."IS_BUILDING_LICENSE_VERIFIED" then 'N' end AS "BUILDING_LICENSE_VERIFIED_FLAG", case when lr."IS_REGISTRATION_POSSIBLE" then 'Y' when not lr."IS_REGISTRATION_POSSIBLE" then 'N' end AS "REGISTRATION_POSSIBLE_FLAG", case when lr."IS_MORTGAGE_POSSIBLE" then 'Y' when not lr."IS_MORTGAGE_POSSIBLE" then 'N' end AS "MORTGAGE_POSSIBLE_FLAG", case when lr."IS_ENCUMBRANCE_FREE" then 'Y' when not lr."IS_ENCUMBRANCE_FREE" then 'N' end AS "ENCUMBRANCE_FREE_FLAG", case when lr."IS_TITLE_DEED_VERIFIED" then 'Y' when not lr."IS_TITLE_DEED_VERIFIED" then 'N' end AS "TITLE_DEED_VERIFIED_FLAG", case when lr."LEGAL_REVIEW_ID" is not null and lr."IS_OWNERSHIP_VERIFIED" and lr."IS_BUILDING_LICENSE_VERIFIED" and lr."IS_REGISTRATION_POSSIBLE" and lr."IS_MORTGAGE_POSSIBLE" and lr."IS_ENCUMBRANCE_FREE" and lr."IS_TITLE_DEED_VERIFIED" then 'Y' else 'N' end "LEGAL_READY_FLAG"
        from "MTG_PURCHASED_PORTFOLIOS" p
        left join "MTG_LEGAL_REVIEWS" lr on lr."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        ),
        "FNV_V_PORTFOLIO_READINESS" AS (
        with f as (select p."PORTFOLIO_ID", p."PORTFOLIO_NO", case when dc."DOCUMENT_READY_FLAG" = 'Y' then 'Y' else 'N' end "DOCUMENT_READY_FLAG", case when exists (select 1
        from "MTG_DUE_DILIGENCES" dd
        where dd."PORTFOLIO_ID" = p."PORTFOLIO_ID" and dd."IS_EXCEPTION") then 'N' else 'Y' end "DD_READY_FLAG", case when exists (select 1
        from "MTG_VALUATIONS" v
        where v."PORTFOLIO_ID" = p."PORTFOLIO_ID") then 'Y' else 'N' end "VALUATION_READY_FLAG", case when ls."LEGAL_READY_FLAG" = 'Y' then 'Y' else 'N' end "LEGAL_READY_FLAG", case when exists (select 1
        from "MTG_FINANCIAL_STUDIES" fs
        where fs."PORTFOLIO_ID" = p."PORTFOLIO_ID") then 'Y' else 'N' end "FINANCE_READY_FLAG", case when cc."COVERAGE_OK_FLAG" = 'Y' then 'Y' else 'N' end "CHEQUE_READY_FLAG", case when gs."GUARANTEE_READY_FLAG" = 'Y' then 'Y' else 'N' end "GUARANTEE_READY_FLAG", case when exists (select 1
        from "FNV_V_PAYMENT_REGULARITY" pr
        where pr."PORTFOLIO_ID" = p."PORTFOLIO_ID" and (pr."PAYMENT_COUNT" < 12 or pr."PROBLEM_COUNT" > 0)) then 'N' else 'Y' end "PAYMENT_HISTORY_READY_FLAG"
        from "MTG_PURCHASED_PORTFOLIOS" p
        left join "FNV_V_DOCUMENT_COMPLETENESS" dc on dc."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        left join "FNV_V_LEGAL_STATUS" ls on ls."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        left join "FNV_V_CHEQUE_COVERAGE" cc on cc."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        left join "FNV_V_GUARANTEE_STATUS" gs on gs."PORTFOLIO_ID" = p."PORTFOLIO_ID") select f.*, case when "DOCUMENT_READY_FLAG" = 'Y' and "DD_READY_FLAG" = 'Y' and "VALUATION_READY_FLAG" = 'Y' and "LEGAL_READY_FLAG" = 'Y' and "FINANCE_READY_FLAG" = 'Y' and "CHEQUE_READY_FLAG" = 'Y' and "GUARANTEE_READY_FLAG" = 'Y' and "PAYMENT_HISTORY_READY_FLAG" = 'Y' then 'Y' else 'N' end "READY_FOR_SUBMISSION_FLAG"
        from f
        ),
        "FNV_V_PORTFOLIO_SUMMARY" AS (
        select pf."PORTFOLIO_ID", pf."PORTFOLIO_NO", pf."REQUEST_DATE", pf."PORTFOLIO_STATUS_CODE", s."STATUS_NAME_AR", s."STATUS_NAME_EN", d."DEVELOPER_ID", d."DEVELOPER_CODE", d."LEGAL_NAME_AR" as "DEVELOPER_NAME_AR", d."LEGAL_NAME_EN" as "DEVELOPER_NAME_EN", d."LEGAL_NAME_AR", d."LEGAL_NAME_EN", p."PROJECT_ID", p."PROJECT_CODE", p."PROJECT_NAME_AR", p."PROJECT_NAME_EN", pf."FACE_VALUE", pf."OUTSTANDING_VALUE", pf."PROPOSED_PURCHASE_VALUE", pf."EXPECTED_RETURN_AMOUNT", pf."TERM_MONTHS", pf."ADMIN_EXPENSE_AMOUNT", pf."CURRENCY_CODE", pf."CURRENT_APPROVAL_STEP", count(pa."PORTFOLIO_ACCOUNT_ID") as "ACCOUNT_COUNT", coalesce(sum(pa."ARREARS_AMOUNT"), 0) as "TOTAL_ARREARS"
        from "MTG_PURCHASED_PORTFOLIOS" pf
        join "MTG_LKP_PORTFOLIO_STATUSES" s on s."STATUS_CODE" = pf."PORTFOLIO_STATUS_CODE"
        join "MTG_DEVELOPERS" d on d."DEVELOPER_ID" = pf."DEVELOPER_ID"
        join "MTG_PROJECTS" p on p."PROJECT_ID" = pf."PROJECT_ID"
        left join "MTG_PURCHASED_PORTFOLIO_ACCOUNTS" pa on pa."PORTFOLIO_ID" = pf."PORTFOLIO_ID"
        group by pf."PORTFOLIO_ID", pf."PORTFOLIO_NO", pf."REQUEST_DATE", pf."PORTFOLIO_STATUS_CODE", s."STATUS_NAME_AR", s."STATUS_NAME_EN", d."DEVELOPER_ID", d."DEVELOPER_CODE", d."LEGAL_NAME_AR", d."LEGAL_NAME_EN", p."PROJECT_ID", p."PROJECT_CODE", p."PROJECT_NAME_AR", p."PROJECT_NAME_EN", pf."FACE_VALUE", pf."OUTSTANDING_VALUE", pf."PROPOSED_PURCHASE_VALUE", pf."EXPECTED_RETURN_AMOUNT", pf."TERM_MONTHS", pf."ADMIN_EXPENSE_AMOUNT", pf."CURRENCY_CODE", pf."CURRENT_APPROVAL_STEP"
        ),
        "FNV_V_PORTFOLIO_WORKLIST" AS (
        select s.*, r."DOCUMENT_READY_FLAG", r."DD_READY_FLAG", r."VALUATION_READY_FLAG", r."LEGAL_READY_FLAG", r."FINANCE_READY_FLAG", r."CHEQUE_READY_FLAG", r."GUARANTEE_READY_FLAG", r."PAYMENT_HISTORY_READY_FLAG", r."READY_FOR_SUBMISSION_FLAG", current_date - (s."REQUEST_DATE")::date as "AGE_DAYS"
        from "FNV_V_PORTFOLIO_SUMMARY" s
        left join "FNV_V_PORTFOLIO_READINESS" r on r."PORTFOLIO_ID" = s."PORTFOLIO_ID"
        )
        select w."PORTFOLIO_ID", w."PORTFOLIO_NO", coalesce(w."LEGAL_NAME_EN", '-') "DEVELOPER", coalesce(w."PROJECT_NAME_EN", '-') "PROJECT", w."STATUS_NAME_EN" "STATUS", w."AGE_DAYS", w."PROPOSED_PURCHASE_VALUE", w."OUTSTANDING_VALUE", w."TOTAL_ARREARS", dc."DOCUMENT_COMPLETION_PCT", cc."CHEQUE_COVERAGE_PCT", (select count(*)
        from "FNV_V_PORTFOLIO_EXCEPTIONS" e
        where e."PORTFOLIO_ID" = w."PORTFOLIO_ID") "OPEN_EXCEPTIONS", w."READY_FOR_SUBMISSION_FLAG"
        from "FNV_V_PORTFOLIO_WORKLIST" w
        left join "FNV_V_DOCUMENT_COMPLETENESS" dc on dc."PORTFOLIO_ID" = w."PORTFOLIO_ID"
        left join "FNV_V_CHEQUE_COVERAGE" cc on cc."PORTFOLIO_ID" = w."PORTFOLIO_ID"
        where w."PORTFOLIO_STATUS_CODE" <> 'CLOSED'
        order by "OPEN_EXCEPTIONS" desc, w."AGE_DAYS" desc, w."PORTFOLIO_NO"
        """;

        public const string P702_OPEN_EXCEPTIONS = """
        with "FNV_V_CHEQUE_COVERAGE" AS (
        select pf."PORTFOLIO_ID", pf."PORTFOLIO_NO", pf."OUTSTANDING_VALUE", pf."EXPECTED_RETURN_AMOUNT", pf."OUTSTANDING_VALUE" + pf."EXPECTED_RETURN_AMOUNT" as "REQUIRED_COVERAGE_AMOUNT", coalesce(sum(c."CHEQUE_AMOUNT"), 0) as "CHEQUE_TOTAL_AMOUNT", case when (pf."OUTSTANDING_VALUE" + pf."EXPECTED_RETURN_AMOUNT") = 0 then null else round(coalesce(sum(c."CHEQUE_AMOUNT"), 0) / ((pf."OUTSTANDING_VALUE" + pf."EXPECTED_RETURN_AMOUNT"))::numeric * 100, 2) end as "CHEQUE_COVERAGE_PCT", case when coalesce(sum(c."CHEQUE_AMOUNT"), 0) >= (pf."OUTSTANDING_VALUE" + pf."EXPECTED_RETURN_AMOUNT") then 'Y' else 'N' end as "COVERAGE_OK_FLAG"
        from "MTG_PURCHASED_PORTFOLIOS" pf
        left join "MTG_PURCHASED_PORTFOLIO_CHEQUES" c on c."PORTFOLIO_ID" = pf."PORTFOLIO_ID"
        group by pf."PORTFOLIO_ID", pf."PORTFOLIO_NO", pf."OUTSTANDING_VALUE", pf."EXPECTED_RETURN_AMOUNT"
        ),
        "FNV_V_PAYMENT_REGULARITY" AS (
        select pa."PORTFOLIO_ACCOUNT_ID", pa."PORTFOLIO_ID", pa."INVESTOR_ID", i."INVESTOR_CODE", i."FULL_NAME_AR", i."FULL_NAME_EN", count(ap."PAYMENT_ID") as "PAYMENT_COUNT", sum(case when ap."PAYMENT_STATUS_CODE" = 'PAID' then 1 else 0 end) as "PAID_COUNT", sum(case when ap."PAYMENT_STATUS_CODE" = 'LATE' then 1 else 0 end) as "LATE_COUNT", sum(case when ap."PAYMENT_STATUS_CODE" in ('PARTIAL', 'UNPAID') then 1 else 0 end) as "PROBLEM_COUNT", max(ap."DAYS_LATE") as "MAX_DAYS_LATE", sum(ap."DUE_AMOUNT") as "TOTAL_DUE", sum(ap."PAID_AMOUNT") as "TOTAL_PAID"
        from "MTG_PURCHASED_PORTFOLIO_ACCOUNTS" pa
        join "MTG_INVESTORS" i on i."INVESTOR_ID" = pa."INVESTOR_ID"
        left join "MTG_ACCOUNT_PAYMENTS" ap on ap."PORTFOLIO_ACCOUNT_ID" = pa."PORTFOLIO_ACCOUNT_ID"
        group by pa."PORTFOLIO_ACCOUNT_ID", pa."PORTFOLIO_ID", pa."INVESTOR_ID", i."INVESTOR_CODE", i."FULL_NAME_AR", i."FULL_NAME_EN"
        ),
        "FNV_V_PORTFOLIO_EXCEPTIONS" AS (
        select p."PORTFOLIO_ID", p."PORTFOLIO_NO", 'DUE_DILIGENCE' "EXCEPTION_TYPE", dd."CHECK_TYPE_CODE" "EXCEPTION_CODE", dd."FINDINGS" "EXCEPTION_DETAILS"
        from "MTG_PURCHASED_PORTFOLIOS" p
        join "MTG_DUE_DILIGENCES" dd on dd."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        where dd."IS_EXCEPTION"
        union all select p."PORTFOLIO_ID", p."PORTFOLIO_NO", 'PAYMENT_HISTORY', 'PAYMENT_IRREGULARITY', (concat('Payment problems found for investor ', pr."FULL_NAME_EN"))
        from "MTG_PURCHASED_PORTFOLIOS" p
        join "FNV_V_PAYMENT_REGULARITY" pr on pr."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        where pr."PAYMENT_COUNT" < 12 or pr."PROBLEM_COUNT" > 0
        union all select p."PORTFOLIO_ID", p."PORTFOLIO_NO", 'CHEQUE_COVERAGE', 'INSUFFICIENT_COVERAGE', ('Cheque coverage is below required amount')
        from "MTG_PURCHASED_PORTFOLIOS" p
        join "FNV_V_CHEQUE_COVERAGE" cc on cc."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        where cc."COVERAGE_OK_FLAG" = 'N'
        )
        select e."PORTFOLIO_ID", e."PORTFOLIO_NO", coalesce(d."LEGAL_NAME_EN", '-') "DEVELOPER", coalesce(pr."PROJECT_NAME_EN", '-') "PROJECT", e."EXCEPTION_TYPE", e."EXCEPTION_CODE", substr(e."EXCEPTION_DETAILS", 1, 4000) "EXCEPTION_DETAILS"
        from "FNV_V_PORTFOLIO_EXCEPTIONS" e
        join "MTG_PURCHASED_PORTFOLIOS" p on p."PORTFOLIO_ID" = e."PORTFOLIO_ID"
        join "MTG_DEVELOPERS" d on d."DEVELOPER_ID" = p."DEVELOPER_ID"
        join "MTG_PROJECTS" pr on pr."PROJECT_ID" = p."PROJECT_ID"
        order by e."PORTFOLIO_NO", e."EXCEPTION_TYPE", e."EXCEPTION_CODE"
        """;

        public const string P703_DOCUMENT_EXPIRY_MONITOR = """
        with "FNV_V_MIS_DOCUMENT_EXPIRY" AS (
        select d."DOCUMENT_ID", d."PORTFOLIO_ID", p."PORTFOLIO_NO", d."DOCUMENT_TYPE_CODE", rt."DOCUMENT_TYPE_NAME_AR", rt."DOCUMENT_TYPE_NAME", d."EXPIRY_DATE", d."EXPIRY_DATE" - current_date "DAYS_TO_EXPIRY"
        from "MTG_PURCHASED_PORTFOLIO_DOCUMENTS" d
        join "MTG_PURCHASED_PORTFOLIOS" p on p."PORTFOLIO_ID" = d."PORTFOLIO_ID"
        join "ADM_LKP_DOCUMENT_TYPES" rt on rt."DOCUMENT_TYPE_CODE" = d."DOCUMENT_TYPE_CODE"
        where d."EXPIRY_DATE" is not null
        )
        select "DOCUMENT_ID", "PORTFOLIO_ID", "PORTFOLIO_NO", "DOCUMENT_TYPE_CODE", "DOCUMENT_TYPE_NAME" "DOCUMENT_TYPE", "EXPIRY_DATE", "DAYS_TO_EXPIRY", case when "DAYS_TO_EXPIRY" < 0 then 'Expired' when "DAYS_TO_EXPIRY" <= 30 then 'Expiring <= 30 Days30 ' else 'Valid' end "EXPIRY_STATUS"
        from "FNV_V_MIS_DOCUMENT_EXPIRY"
        order by "DAYS_TO_EXPIRY", "PORTFOLIO_NO"
        """;

        public const string P704_PAYMENT_PERFORMANCE = """
        with "FNV_V_PAYMENT_REGULARITY" AS (
        select pa."PORTFOLIO_ACCOUNT_ID", pa."PORTFOLIO_ID", pa."INVESTOR_ID", i."INVESTOR_CODE", i."FULL_NAME_AR", i."FULL_NAME_EN", count(ap."PAYMENT_ID") as "PAYMENT_COUNT", sum(case when ap."PAYMENT_STATUS_CODE" = 'PAID' then 1 else 0 end) as "PAID_COUNT", sum(case when ap."PAYMENT_STATUS_CODE" = 'LATE' then 1 else 0 end) as "LATE_COUNT", sum(case when ap."PAYMENT_STATUS_CODE" in ('PARTIAL', 'UNPAID') then 1 else 0 end) as "PROBLEM_COUNT", max(ap."DAYS_LATE") as "MAX_DAYS_LATE", sum(ap."DUE_AMOUNT") as "TOTAL_DUE", sum(ap."PAID_AMOUNT") as "TOTAL_PAID"
        from "MTG_PURCHASED_PORTFOLIO_ACCOUNTS" pa
        join "MTG_INVESTORS" i on i."INVESTOR_ID" = pa."INVESTOR_ID"
        left join "MTG_ACCOUNT_PAYMENTS" ap on ap."PORTFOLIO_ACCOUNT_ID" = pa."PORTFOLIO_ACCOUNT_ID"
        group by pa."PORTFOLIO_ACCOUNT_ID", pa."PORTFOLIO_ID", pa."INVESTOR_ID", i."INVESTOR_CODE", i."FULL_NAME_AR", i."FULL_NAME_EN"
        ),
        "FNV_V_MIS_PAYMENT_PERFORMANCE" AS (
        select p."PORTFOLIO_ID", p."PORTFOLIO_NO", count(pr."PORTFOLIO_ACCOUNT_ID") "ACCOUNT_COUNT", sum(case when pr."LATE_COUNT" = 0 and pr."PROBLEM_COUNT" = 0 then 1 else 0 end) "REGULAR_ACCOUNTS", sum(case when pr."LATE_COUNT" > 0 then 1 else 0 end) "LATE_ACCOUNTS", sum(case when pr."PROBLEM_COUNT" > 0 then 1 else 0 end) "PROBLEM_ACCOUNTS", sum(pa."ARREARS_AMOUNT") "ARREARS_VALUE"
        from "MTG_PURCHASED_PORTFOLIOS" p
        left join "FNV_V_PAYMENT_REGULARITY" pr on pr."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        left join "MTG_PURCHASED_PORTFOLIO_ACCOUNTS" pa on pa."PORTFOLIO_ACCOUNT_ID" = pr."PORTFOLIO_ACCOUNT_ID"
        group by p."PORTFOLIO_ID", p."PORTFOLIO_NO"
        )
        select m."PORTFOLIO_ID", m."PORTFOLIO_NO", coalesce(d."LEGAL_NAME_EN", '-') "DEVELOPER", coalesce(pr."PROJECT_NAME_EN", '-') "PROJECT", m."ACCOUNT_COUNT", m."REGULAR_ACCOUNTS", m."LATE_ACCOUNTS", m."PROBLEM_ACCOUNTS", m."ARREARS_VALUE", case when m."ACCOUNT_COUNT" = 0 then null else round(m."REGULAR_ACCOUNTS" / (m."ACCOUNT_COUNT")::numeric * 100, 2) end "REGULARITY_PCT"
        from "FNV_V_MIS_PAYMENT_PERFORMANCE" m
        join "MTG_PURCHASED_PORTFOLIOS" p on p."PORTFOLIO_ID" = m."PORTFOLIO_ID"
        join "MTG_DEVELOPERS" d on d."DEVELOPER_ID" = p."DEVELOPER_ID"
        join "MTG_PROJECTS" pr on pr."PROJECT_ID" = p."PROJECT_ID"
        order by m."ARREARS_VALUE" desc nulls last, m."PROBLEM_ACCOUNTS" desc, m."PORTFOLIO_NO"
        """;

        public const string P705_CHEQUE_COVERAGE_MONITOR = """
        with "FNV_V_CHEQUE_COVERAGE" AS (
        select pf."PORTFOLIO_ID", pf."PORTFOLIO_NO", pf."OUTSTANDING_VALUE", pf."EXPECTED_RETURN_AMOUNT", pf."OUTSTANDING_VALUE" + pf."EXPECTED_RETURN_AMOUNT" as "REQUIRED_COVERAGE_AMOUNT", coalesce(sum(c."CHEQUE_AMOUNT"), 0) as "CHEQUE_TOTAL_AMOUNT", case when (pf."OUTSTANDING_VALUE" + pf."EXPECTED_RETURN_AMOUNT") = 0 then null else round(coalesce(sum(c."CHEQUE_AMOUNT"), 0) / ((pf."OUTSTANDING_VALUE" + pf."EXPECTED_RETURN_AMOUNT"))::numeric * 100, 2) end as "CHEQUE_COVERAGE_PCT", case when coalesce(sum(c."CHEQUE_AMOUNT"), 0) >= (pf."OUTSTANDING_VALUE" + pf."EXPECTED_RETURN_AMOUNT") then 'Y' else 'N' end as "COVERAGE_OK_FLAG"
        from "MTG_PURCHASED_PORTFOLIOS" pf
        left join "MTG_PURCHASED_PORTFOLIO_CHEQUES" c on c."PORTFOLIO_ID" = pf."PORTFOLIO_ID"
        group by pf."PORTFOLIO_ID", pf."PORTFOLIO_NO", pf."OUTSTANDING_VALUE", pf."EXPECTED_RETURN_AMOUNT"
        )
        select c."PORTFOLIO_ID", c."PORTFOLIO_NO", coalesce(d."LEGAL_NAME_EN", '-') "DEVELOPER", c."OUTSTANDING_VALUE", c."EXPECTED_RETURN_AMOUNT", c."REQUIRED_COVERAGE_AMOUNT", c."CHEQUE_TOTAL_AMOUNT", c."CHEQUE_COVERAGE_PCT", c."COVERAGE_OK_FLAG"
        from "FNV_V_CHEQUE_COVERAGE" c
        join "MTG_PURCHASED_PORTFOLIOS" p on p."PORTFOLIO_ID" = c."PORTFOLIO_ID"
        join "MTG_DEVELOPERS" d on d."DEVELOPER_ID" = p."DEVELOPER_ID"
        order by c."COVERAGE_OK_FLAG", c."CHEQUE_COVERAGE_PCT" nulls first, c."PORTFOLIO_NO"
        """;

        public const string P706_READINESS_MATRIX = """
        with "FNV_V_CHEQUE_COVERAGE" AS (
        select pf."PORTFOLIO_ID", pf."PORTFOLIO_NO", pf."OUTSTANDING_VALUE", pf."EXPECTED_RETURN_AMOUNT", pf."OUTSTANDING_VALUE" + pf."EXPECTED_RETURN_AMOUNT" as "REQUIRED_COVERAGE_AMOUNT", coalesce(sum(c."CHEQUE_AMOUNT"), 0) as "CHEQUE_TOTAL_AMOUNT", case when (pf."OUTSTANDING_VALUE" + pf."EXPECTED_RETURN_AMOUNT") = 0 then null else round(coalesce(sum(c."CHEQUE_AMOUNT"), 0) / ((pf."OUTSTANDING_VALUE" + pf."EXPECTED_RETURN_AMOUNT"))::numeric * 100, 2) end as "CHEQUE_COVERAGE_PCT", case when coalesce(sum(c."CHEQUE_AMOUNT"), 0) >= (pf."OUTSTANDING_VALUE" + pf."EXPECTED_RETURN_AMOUNT") then 'Y' else 'N' end as "COVERAGE_OK_FLAG"
        from "MTG_PURCHASED_PORTFOLIOS" pf
        left join "MTG_PURCHASED_PORTFOLIO_CHEQUES" c on c."PORTFOLIO_ID" = pf."PORTFOLIO_ID"
        group by pf."PORTFOLIO_ID", pf."PORTFOLIO_NO", pf."OUTSTANDING_VALUE", pf."EXPECTED_RETURN_AMOUNT"
        ),
        "FNV_V_DOCUMENT_COMPLETENESS" AS (
        with req as (select count(*) "REQUIRED_COUNT"
        from "ADM_LKP_DOCUMENT_TYPES"
        where "IS_MANDATORY" and "IS_ACTIVE"), doc as (select "PORTFOLIO_ID", count(distinct "DOCUMENT_TYPE_CODE") "RECEIVED_REQUIRED_COUNT"
        from "MTG_PURCHASED_PORTFOLIO_DOCUMENTS" d
        where exists (select 1
        from "ADM_LKP_DOCUMENT_TYPES" r
        where r."DOCUMENT_TYPE_CODE" = d."DOCUMENT_TYPE_CODE" and r."IS_MANDATORY" and r."IS_ACTIVE")
        group by "PORTFOLIO_ID") select p."PORTFOLIO_ID", p."PORTFOLIO_NO", r."REQUIRED_COUNT", coalesce(d."RECEIVED_REQUIRED_COUNT", 0) "RECEIVED_REQUIRED_COUNT", greatest(r."REQUIRED_COUNT" - coalesce(d."RECEIVED_REQUIRED_COUNT", 0), 0) "MISSING_REQUIRED_COUNT", case when r."REQUIRED_COUNT" = 0 then 100 else round(coalesce(d."RECEIVED_REQUIRED_COUNT", 0) / (r."REQUIRED_COUNT")::numeric * 100, 2) end "DOCUMENT_COMPLETION_PCT", case when coalesce(d."RECEIVED_REQUIRED_COUNT", 0) >= r."REQUIRED_COUNT" then 'Y' else 'N' end "DOCUMENT_READY_FLAG"
        from "MTG_PURCHASED_PORTFOLIOS" p
        cross join req r
        left join doc d on d."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        ),
        "FNV_V_GUARANTEE_STATUS" AS (
        with req as (select count(*) "REQUIRED_COUNT"
        from "ADM_LKP_GUARANTEE_TYPES"
        where "IS_MANDATORY" and "IS_ACTIVE"), got as (select "PORTFOLIO_ID", count(distinct "GUARANTEE_TYPE_CODE") "VERIFIED_REQUIRED_COUNT"
        from "MTG_GUARANTEES" g
        where "IS_VERIFIED" and exists (select 1
        from "ADM_LKP_GUARANTEE_TYPES" r
        where r."GUARANTEE_TYPE_CODE" = g."GUARANTEE_TYPE_CODE" and r."IS_MANDATORY" and r."IS_ACTIVE")
        group by "PORTFOLIO_ID") select p."PORTFOLIO_ID", p."PORTFOLIO_NO", r."REQUIRED_COUNT", coalesce(g."VERIFIED_REQUIRED_COUNT", 0) "VERIFIED_REQUIRED_COUNT", greatest(r."REQUIRED_COUNT" - coalesce(g."VERIFIED_REQUIRED_COUNT", 0), 0) "MISSING_REQUIRED_COUNT", case when coalesce(g."VERIFIED_REQUIRED_COUNT", 0) >= r."REQUIRED_COUNT" then 'Y' else 'N' end "GUARANTEE_READY_FLAG"
        from "MTG_PURCHASED_PORTFOLIOS" p
        cross join req r
        left join got g on g."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        ),
        "FNV_V_LEGAL_STATUS" AS (
        select p."PORTFOLIO_ID", p."PORTFOLIO_NO", lr."LEGAL_REVIEW_ID", case when lr."IS_OWNERSHIP_VERIFIED" then 'Y' when not lr."IS_OWNERSHIP_VERIFIED" then 'N' end AS "OWNERSHIP_VERIFIED_FLAG", case when lr."IS_BUILDING_LICENSE_VERIFIED" then 'Y' when not lr."IS_BUILDING_LICENSE_VERIFIED" then 'N' end AS "BUILDING_LICENSE_VERIFIED_FLAG", case when lr."IS_REGISTRATION_POSSIBLE" then 'Y' when not lr."IS_REGISTRATION_POSSIBLE" then 'N' end AS "REGISTRATION_POSSIBLE_FLAG", case when lr."IS_MORTGAGE_POSSIBLE" then 'Y' when not lr."IS_MORTGAGE_POSSIBLE" then 'N' end AS "MORTGAGE_POSSIBLE_FLAG", case when lr."IS_ENCUMBRANCE_FREE" then 'Y' when not lr."IS_ENCUMBRANCE_FREE" then 'N' end AS "ENCUMBRANCE_FREE_FLAG", case when lr."IS_TITLE_DEED_VERIFIED" then 'Y' when not lr."IS_TITLE_DEED_VERIFIED" then 'N' end AS "TITLE_DEED_VERIFIED_FLAG", case when lr."LEGAL_REVIEW_ID" is not null and lr."IS_OWNERSHIP_VERIFIED" and lr."IS_BUILDING_LICENSE_VERIFIED" and lr."IS_REGISTRATION_POSSIBLE" and lr."IS_MORTGAGE_POSSIBLE" and lr."IS_ENCUMBRANCE_FREE" and lr."IS_TITLE_DEED_VERIFIED" then 'Y' else 'N' end "LEGAL_READY_FLAG"
        from "MTG_PURCHASED_PORTFOLIOS" p
        left join "MTG_LEGAL_REVIEWS" lr on lr."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        ),
        "FNV_V_PAYMENT_REGULARITY" AS (
        select pa."PORTFOLIO_ACCOUNT_ID", pa."PORTFOLIO_ID", pa."INVESTOR_ID", i."INVESTOR_CODE", i."FULL_NAME_AR", i."FULL_NAME_EN", count(ap."PAYMENT_ID") as "PAYMENT_COUNT", sum(case when ap."PAYMENT_STATUS_CODE" = 'PAID' then 1 else 0 end) as "PAID_COUNT", sum(case when ap."PAYMENT_STATUS_CODE" = 'LATE' then 1 else 0 end) as "LATE_COUNT", sum(case when ap."PAYMENT_STATUS_CODE" in ('PARTIAL', 'UNPAID') then 1 else 0 end) as "PROBLEM_COUNT", max(ap."DAYS_LATE") as "MAX_DAYS_LATE", sum(ap."DUE_AMOUNT") as "TOTAL_DUE", sum(ap."PAID_AMOUNT") as "TOTAL_PAID"
        from "MTG_PURCHASED_PORTFOLIO_ACCOUNTS" pa
        join "MTG_INVESTORS" i on i."INVESTOR_ID" = pa."INVESTOR_ID"
        left join "MTG_ACCOUNT_PAYMENTS" ap on ap."PORTFOLIO_ACCOUNT_ID" = pa."PORTFOLIO_ACCOUNT_ID"
        group by pa."PORTFOLIO_ACCOUNT_ID", pa."PORTFOLIO_ID", pa."INVESTOR_ID", i."INVESTOR_CODE", i."FULL_NAME_AR", i."FULL_NAME_EN"
        ),
        "FNV_V_PORTFOLIO_READINESS" AS (
        with f as (select p."PORTFOLIO_ID", p."PORTFOLIO_NO", case when dc."DOCUMENT_READY_FLAG" = 'Y' then 'Y' else 'N' end "DOCUMENT_READY_FLAG", case when exists (select 1
        from "MTG_DUE_DILIGENCES" dd
        where dd."PORTFOLIO_ID" = p."PORTFOLIO_ID" and dd."IS_EXCEPTION") then 'N' else 'Y' end "DD_READY_FLAG", case when exists (select 1
        from "MTG_VALUATIONS" v
        where v."PORTFOLIO_ID" = p."PORTFOLIO_ID") then 'Y' else 'N' end "VALUATION_READY_FLAG", case when ls."LEGAL_READY_FLAG" = 'Y' then 'Y' else 'N' end "LEGAL_READY_FLAG", case when exists (select 1
        from "MTG_FINANCIAL_STUDIES" fs
        where fs."PORTFOLIO_ID" = p."PORTFOLIO_ID") then 'Y' else 'N' end "FINANCE_READY_FLAG", case when cc."COVERAGE_OK_FLAG" = 'Y' then 'Y' else 'N' end "CHEQUE_READY_FLAG", case when gs."GUARANTEE_READY_FLAG" = 'Y' then 'Y' else 'N' end "GUARANTEE_READY_FLAG", case when exists (select 1
        from "FNV_V_PAYMENT_REGULARITY" pr
        where pr."PORTFOLIO_ID" = p."PORTFOLIO_ID" and (pr."PAYMENT_COUNT" < 12 or pr."PROBLEM_COUNT" > 0)) then 'N' else 'Y' end "PAYMENT_HISTORY_READY_FLAG"
        from "MTG_PURCHASED_PORTFOLIOS" p
        left join "FNV_V_DOCUMENT_COMPLETENESS" dc on dc."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        left join "FNV_V_LEGAL_STATUS" ls on ls."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        left join "FNV_V_CHEQUE_COVERAGE" cc on cc."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        left join "FNV_V_GUARANTEE_STATUS" gs on gs."PORTFOLIO_ID" = p."PORTFOLIO_ID") select f.*, case when "DOCUMENT_READY_FLAG" = 'Y' and "DD_READY_FLAG" = 'Y' and "VALUATION_READY_FLAG" = 'Y' and "LEGAL_READY_FLAG" = 'Y' and "FINANCE_READY_FLAG" = 'Y' and "CHEQUE_READY_FLAG" = 'Y' and "GUARANTEE_READY_FLAG" = 'Y' and "PAYMENT_HISTORY_READY_FLAG" = 'Y' then 'Y' else 'N' end "READY_FOR_SUBMISSION_FLAG"
        from f
        )
        select r."PORTFOLIO_ID", r."PORTFOLIO_NO", r."DOCUMENT_READY_FLAG", r."DD_READY_FLAG", r."VALUATION_READY_FLAG", r."LEGAL_READY_FLAG", r."FINANCE_READY_FLAG", r."CHEQUE_READY_FLAG", r."GUARANTEE_READY_FLAG", r."PAYMENT_HISTORY_READY_FLAG", r."READY_FOR_SUBMISSION_FLAG"
        from "FNV_V_PORTFOLIO_READINESS" r
        join "MTG_PURCHASED_PORTFOLIOS" p on p."PORTFOLIO_ID" = r."PORTFOLIO_ID"
        order by r."READY_FOR_SUBMISSION_FLAG", r."PORTFOLIO_NO"
        """;

        public const string P711_DEVELOPER_EXPOSURE = """
        with "FNV_V_MIS_DEVELOPER_EXPOSURE" AS (
        select d."DEVELOPER_ID", d."DEVELOPER_CODE", d."LEGAL_NAME_AR", d."LEGAL_NAME_EN", count(distinct pf."PORTFOLIO_ID") "PORTFOLIO_COUNT", count(distinct pf."PROJECT_ID") "PROJECT_COUNT", count(distinct pa."INVESTOR_ID") "INVESTOR_COUNT", sum(pf."FACE_VALUE") "FACE_VALUE", sum(pf."PROPOSED_PURCHASE_VALUE") "PURCHASE_VALUE", sum(pf."OUTSTANDING_VALUE") "OUTSTANDING_EXPOSURE"
        from "MTG_DEVELOPERS" d
        left join "MTG_PURCHASED_PORTFOLIOS" pf on pf."DEVELOPER_ID" = d."DEVELOPER_ID"
        left join "MTG_PURCHASED_PORTFOLIO_ACCOUNTS" pa on pa."PORTFOLIO_ID" = pf."PORTFOLIO_ID"
        group by d."DEVELOPER_ID", d."DEVELOPER_CODE", d."LEGAL_NAME_AR", d."LEGAL_NAME_EN"
        )
        select "DEVELOPER_ID", "DEVELOPER_CODE", coalesce("LEGAL_NAME_EN", '-') "DEVELOPER", "PORTFOLIO_COUNT", "PROJECT_COUNT", "INVESTOR_COUNT", "FACE_VALUE", "PURCHASE_VALUE", "OUTSTANDING_EXPOSURE"
        from "FNV_V_MIS_DEVELOPER_EXPOSURE"
        order by "OUTSTANDING_EXPOSURE" desc, "DEVELOPER_CODE"
        """;

        public const string P712_PROJECT_EXPOSURE = """
        with "FNV_V_MIS_PROJECT_EXPOSURE" AS (
        select p."PROJECT_ID", p."PROJECT_CODE", p."PROJECT_NAME_AR", p."PROJECT_NAME_EN", count(distinct pf."PORTFOLIO_ID") "PORTFOLIO_COUNT", count(distinct pa."INVESTOR_ID") "INVESTOR_COUNT", sum(pf."PROPOSED_PURCHASE_VALUE") "PURCHASE_VALUE", sum(pf."OUTSTANDING_VALUE") "OUTSTANDING_EXPOSURE"
        from "MTG_PROJECTS" p
        left join "MTG_PURCHASED_PORTFOLIOS" pf on pf."PROJECT_ID" = p."PROJECT_ID"
        left join "MTG_PURCHASED_PORTFOLIO_ACCOUNTS" pa on pa."PORTFOLIO_ID" = pf."PORTFOLIO_ID"
        group by p."PROJECT_ID", p."PROJECT_CODE", p."PROJECT_NAME_AR", p."PROJECT_NAME_EN"
        )
        select "PROJECT_ID", "PROJECT_CODE", coalesce("PROJECT_NAME_EN", '-') "PROJECT", "PORTFOLIO_COUNT", "INVESTOR_COUNT", "PURCHASE_VALUE", "OUTSTANDING_EXPOSURE"
        from "FNV_V_MIS_PROJECT_EXPOSURE"
        order by "OUTSTANDING_EXPOSURE" desc, "PROJECT_CODE"
        """;

        public const string P713_PIPELINE_AGING = """
        with "FNV_V_MIS_PIPELINE_AGING" AS (
        select "PORTFOLIO_STATUS_CODE", count(*) "CASE_COUNT", sum("PROPOSED_PURCHASE_VALUE") "PIPELINE_VALUE", round(avg(current_date - ("REQUEST_DATE")::date), 1) "AVG_DAYS", max(current_date - ("REQUEST_DATE")::date) "OLDEST_DAYS"
        from "MTG_PURCHASED_PORTFOLIOS"
        where "PORTFOLIO_STATUS_CODE" not in ('CLOSED')
        group by "PORTFOLIO_STATUS_CODE"
        )
        select a."PORTFOLIO_STATUS_CODE", s."STATUS_NAME_EN" "STATUS", a."CASE_COUNT", a."PIPELINE_VALUE", a."AVG_DAYS", a."OLDEST_DAYS"
        from "FNV_V_MIS_PIPELINE_AGING" a
        join "MTG_LKP_PORTFOLIO_STATUSES" s on s."STATUS_CODE" = a."PORTFOLIO_STATUS_CODE"
        order by s."DISPLAY_SEQ"
        """;

        public const string P714_APPROVAL_TAT = """
        with "FNV_V_MIS_APPROVAL_TAT" AS (
        select a."STEP_CODE", s."STEP_NAME_AR", s."STEP_NAME_EN", count(*) "TASK_COUNT", round(avg(case when a."DECISION_DATE" is not null and a."ASSIGNED_DATE" is not null then a."DECISION_DATE" - a."ASSIGNED_DATE" end), 2) "AVG_TAT_DAYS"
        from "MTG_PURCHASED_PORTFOLIO_APPROVALS" a
        join "MTG_LKP_APPROVAL_STEPS" s on s."STEP_CODE" = a."STEP_CODE"
        group by a."STEP_CODE", s."STEP_NAME_AR", s."STEP_NAME_EN"
        )
        select "STEP_CODE", "STEP_NAME_EN" "APPROVAL_STEP", "TASK_COUNT", "AVG_TAT_DAYS"
        from "FNV_V_MIS_APPROVAL_TAT"
        order by "STEP_CODE"
        """;

        public const string P715_EXCEPTION_SUMMARY = """
        with "FNV_V_CHEQUE_COVERAGE" AS (
        select pf."PORTFOLIO_ID", pf."PORTFOLIO_NO", pf."OUTSTANDING_VALUE", pf."EXPECTED_RETURN_AMOUNT", pf."OUTSTANDING_VALUE" + pf."EXPECTED_RETURN_AMOUNT" as "REQUIRED_COVERAGE_AMOUNT", coalesce(sum(c."CHEQUE_AMOUNT"), 0) as "CHEQUE_TOTAL_AMOUNT", case when (pf."OUTSTANDING_VALUE" + pf."EXPECTED_RETURN_AMOUNT") = 0 then null else round(coalesce(sum(c."CHEQUE_AMOUNT"), 0) / ((pf."OUTSTANDING_VALUE" + pf."EXPECTED_RETURN_AMOUNT"))::numeric * 100, 2) end as "CHEQUE_COVERAGE_PCT", case when coalesce(sum(c."CHEQUE_AMOUNT"), 0) >= (pf."OUTSTANDING_VALUE" + pf."EXPECTED_RETURN_AMOUNT") then 'Y' else 'N' end as "COVERAGE_OK_FLAG"
        from "MTG_PURCHASED_PORTFOLIOS" pf
        left join "MTG_PURCHASED_PORTFOLIO_CHEQUES" c on c."PORTFOLIO_ID" = pf."PORTFOLIO_ID"
        group by pf."PORTFOLIO_ID", pf."PORTFOLIO_NO", pf."OUTSTANDING_VALUE", pf."EXPECTED_RETURN_AMOUNT"
        ),
        "FNV_V_PAYMENT_REGULARITY" AS (
        select pa."PORTFOLIO_ACCOUNT_ID", pa."PORTFOLIO_ID", pa."INVESTOR_ID", i."INVESTOR_CODE", i."FULL_NAME_AR", i."FULL_NAME_EN", count(ap."PAYMENT_ID") as "PAYMENT_COUNT", sum(case when ap."PAYMENT_STATUS_CODE" = 'PAID' then 1 else 0 end) as "PAID_COUNT", sum(case when ap."PAYMENT_STATUS_CODE" = 'LATE' then 1 else 0 end) as "LATE_COUNT", sum(case when ap."PAYMENT_STATUS_CODE" in ('PARTIAL', 'UNPAID') then 1 else 0 end) as "PROBLEM_COUNT", max(ap."DAYS_LATE") as "MAX_DAYS_LATE", sum(ap."DUE_AMOUNT") as "TOTAL_DUE", sum(ap."PAID_AMOUNT") as "TOTAL_PAID"
        from "MTG_PURCHASED_PORTFOLIO_ACCOUNTS" pa
        join "MTG_INVESTORS" i on i."INVESTOR_ID" = pa."INVESTOR_ID"
        left join "MTG_ACCOUNT_PAYMENTS" ap on ap."PORTFOLIO_ACCOUNT_ID" = pa."PORTFOLIO_ACCOUNT_ID"
        group by pa."PORTFOLIO_ACCOUNT_ID", pa."PORTFOLIO_ID", pa."INVESTOR_ID", i."INVESTOR_CODE", i."FULL_NAME_AR", i."FULL_NAME_EN"
        ),
        "FNV_V_PORTFOLIO_EXCEPTIONS" AS (
        select p."PORTFOLIO_ID", p."PORTFOLIO_NO", 'DUE_DILIGENCE' "EXCEPTION_TYPE", dd."CHECK_TYPE_CODE" "EXCEPTION_CODE", dd."FINDINGS" "EXCEPTION_DETAILS"
        from "MTG_PURCHASED_PORTFOLIOS" p
        join "MTG_DUE_DILIGENCES" dd on dd."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        where dd."IS_EXCEPTION"
        union all select p."PORTFOLIO_ID", p."PORTFOLIO_NO", 'PAYMENT_HISTORY', 'PAYMENT_IRREGULARITY', (concat('Payment problems found for investor ', pr."FULL_NAME_EN"))
        from "MTG_PURCHASED_PORTFOLIOS" p
        join "FNV_V_PAYMENT_REGULARITY" pr on pr."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        where pr."PAYMENT_COUNT" < 12 or pr."PROBLEM_COUNT" > 0
        union all select p."PORTFOLIO_ID", p."PORTFOLIO_NO", 'CHEQUE_COVERAGE', 'INSUFFICIENT_COVERAGE', ('Cheque coverage is below required amount')
        from "MTG_PURCHASED_PORTFOLIOS" p
        join "FNV_V_CHEQUE_COVERAGE" cc on cc."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        where cc."COVERAGE_OK_FLAG" = 'N'
        ),
        "FNV_V_MIS_EXCEPTION_SUMMARY" AS (
        select "EXCEPTION_TYPE", count(*) "EXCEPTION_COUNT"
        from "FNV_V_PORTFOLIO_EXCEPTIONS"
        group by "EXCEPTION_TYPE"
        )
        select "EXCEPTION_TYPE", "EXCEPTION_COUNT"
        from "FNV_V_MIS_EXCEPTION_SUMMARY"
        order by "EXCEPTION_COUNT" desc, "EXCEPTION_TYPE"
        """;

        public const string P721_PORTFOLIO_SNAPSHOTS = """
        with "FNV_V_MIS_PORTFOLIO_SNAPSHOT" AS (
        select s."SNAPSHOT_ID", s."AS_OF_DATE", s."PORTFOLIO_ID", p."PORTFOLIO_NO", d."DEVELOPER_CODE", coalesce(d."LEGAL_NAME_EN", d."LEGAL_NAME_AR") "DEVELOPER_NAME", pr."PROJECT_CODE", coalesce(pr."PROJECT_NAME_EN", pr."PROJECT_NAME_AR") "PROJECT_NAME", s."OUTSTANDING_VALUE", s."PURCHASE_VALUE", s."CHEQUE_COVERAGE", s."DOCUMENT_COMPLETION_PCT", s."OPEN_EXCEPTION_COUNT", s."CURRENT_STATUS", s."CREATED_AT" AS "CREATED_ON"
        from "MTG_PURCHASED_PORTFOLIO_SNAPSHOTS" s
        join "MTG_PURCHASED_PORTFOLIOS" p on p."PORTFOLIO_ID" = s."PORTFOLIO_ID"
        join "MTG_DEVELOPERS" d on d."DEVELOPER_ID" = p."DEVELOPER_ID"
        join "MTG_PROJECTS" pr on pr."PROJECT_ID" = p."PROJECT_ID"
        )
        select "SNAPSHOT_ID", "AS_OF_DATE", "PORTFOLIO_ID", "PORTFOLIO_NO", concat("DEVELOPER_CODE", ' - ', "DEVELOPER_NAME") "DEVELOPER", concat("PROJECT_CODE", ' - ', "PROJECT_NAME") "PROJECT", "OUTSTANDING_VALUE", "PURCHASE_VALUE", "CHEQUE_COVERAGE", "DOCUMENT_COMPLETION_PCT", "OPEN_EXCEPTION_COUNT", "CURRENT_STATUS", "CREATED_ON"
        from "FNV_V_MIS_PORTFOLIO_SNAPSHOT"
        order by "AS_OF_DATE" desc, "PORTFOLIO_NO"
        """;

        public const string P722_ACCOUNT_SNAPSHOTS = """
        with "FNV_V_MIS_ACCOUNT_SNAPSHOT" AS (
        select s."SNAPSHOT_ID", s."AS_OF_DATE", s."PORTFOLIO_ACCOUNT_ID", p."PORTFOLIO_ID", p."PORTFOLIO_NO", i."INVESTOR_CODE", coalesce(i."FULL_NAME_EN", i."FULL_NAME_AR") "INVESTOR_NAME", u."UNIT_CODE", s."OUTSTANDING_VALUE", s."ARREARS_AMOUNT", s."NEXT_DUE_DATE", s."PAYMENT_STATUS", s."CREATED_AT" AS "CREATED_ON"
        from "MTG_ACCOUNT_SNAPSHOTS" s
        join "MTG_PURCHASED_PORTFOLIO_ACCOUNTS" a on a."PORTFOLIO_ACCOUNT_ID" = s."PORTFOLIO_ACCOUNT_ID"
        join "MTG_PURCHASED_PORTFOLIOS" p on p."PORTFOLIO_ID" = a."PORTFOLIO_ID"
        join "MTG_INVESTORS" i on i."INVESTOR_ID" = a."INVESTOR_ID"
        join "MTG_PROJECT_UNITS" u on u."UNIT_ID" = a."UNIT_ID"
        )
        select "SNAPSHOT_ID", "AS_OF_DATE", "PORTFOLIO_ACCOUNT_ID", "PORTFOLIO_ID", "PORTFOLIO_NO", "INVESTOR_CODE", "INVESTOR_NAME", "UNIT_CODE", "OUTSTANDING_VALUE", "ARREARS_AMOUNT", "NEXT_DUE_DATE", "PAYMENT_STATUS", "CREATED_ON"
        from "FNV_V_MIS_ACCOUNT_SNAPSHOT"
        order by "AS_OF_DATE" desc, "PORTFOLIO_NO", "INVESTOR_CODE", "UNIT_CODE"
        """;

        public const string P730_PORTFOLIO_ACQUISITION_REGISTER = """
        select p."PORTFOLIO_ID", p."PORTFOLIO_NO", d."DEVELOPER_CODE", d."LEGAL_NAME_EN" "DEVELOPER_NAME_EN", d."LEGAL_NAME_AR" "DEVELOPER_NAME_AR", pr."PROJECT_CODE", pr."PROJECT_NAME_EN", pr."PROJECT_NAME_AR", p."REQUEST_DATE", p."PORTFOLIO_STATUS_CODE", ps."STATUS_NAME_EN", ps."STATUS_NAME_AR", p."CURRENCY_CODE", p."FACE_VALUE", p."OUTSTANDING_VALUE", p."PROPOSED_PURCHASE_VALUE", (p."FACE_VALUE" - p."PROPOSED_PURCHASE_VALUE") "PURCHASE_DISCOUNT_AMOUNT", round(100 * (p."FACE_VALUE" - p."PROPOSED_PURCHASE_VALUE") / (nullif(p."FACE_VALUE", 0))::numeric, 2) "PURCHASE_DISCOUNT_PCT", p."EXPECTED_RETURN_AMOUNT", p."TERM_MONTHS", p."CURRENT_APPROVAL_STEP", p."SUBMITTED_AT" AS "SUBMITTED_DATE", p."APPROVED_AT" AS "APPROVED_DATE", count(distinct a."PORTFOLIO_ACCOUNT_ID") "ACCOUNT_COUNT", s."SETTLEMENT_STATUS_CODE", s."ACCOUNTING_STATUS_CODE", s."SETTLEMENT_DATE"
        from "MTG_PURCHASED_PORTFOLIOS" p
        join "MTG_DEVELOPERS" d on d."DEVELOPER_ID" = p."DEVELOPER_ID"
        join "MTG_PROJECTS" pr on pr."PROJECT_ID" = p."PROJECT_ID"
        left join "MTG_LKP_PORTFOLIO_STATUSES" ps on ps."STATUS_CODE" = p."PORTFOLIO_STATUS_CODE"
        left join "MTG_PURCHASED_PORTFOLIO_ACCOUNTS" a on a."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        left join "MTG_PURCHASED_PORTFOLIO_SETTLEMENTS" s on s."PORTFOLIO_ID" = p."PORTFOLIO_ID" where (@P730_DEVELOPER_ID::bigint is null or p."DEVELOPER_ID" = @P730_DEVELOPER_ID::bigint) and (@P730_PROJECT_ID::bigint is null or p."PROJECT_ID" = @P730_PROJECT_ID::bigint) and (@P730_STATUS_CODE::text is null or p."PORTFOLIO_STATUS_CODE" = @P730_STATUS_CODE::text) and (@P730_DATE_FROM::text is null or p."REQUEST_DATE" >= cast(@P730_DATE_FROM::text as date)) and (@P730_DATE_TO::text is null or p."REQUEST_DATE" < cast(@P730_DATE_TO::text as date) + 1) and (@P730_CURRENCY_CODE::text is null or p."CURRENCY_CODE" = @P730_CURRENCY_CODE::text)
        group by p."PORTFOLIO_ID", p."PORTFOLIO_NO", d."DEVELOPER_CODE", d."LEGAL_NAME_EN", d."LEGAL_NAME_AR", pr."PROJECT_CODE", pr."PROJECT_NAME_EN", pr."PROJECT_NAME_AR", p."REQUEST_DATE", p."PORTFOLIO_STATUS_CODE", ps."STATUS_NAME_EN", ps."STATUS_NAME_AR", p."CURRENCY_CODE", p."FACE_VALUE", p."OUTSTANDING_VALUE", p."PROPOSED_PURCHASE_VALUE", p."EXPECTED_RETURN_AMOUNT", p."TERM_MONTHS", p."CURRENT_APPROVAL_STEP", p."SUBMITTED_AT", p."APPROVED_AT", s."SETTLEMENT_STATUS_CODE", s."ACCOUNTING_STATUS_CODE", s."SETTLEMENT_DATE"
        order by p."REQUEST_DATE" desc, p."PORTFOLIO_NO"
        """;

        public const string P731_PORTFOLIO_ACCOUNT_CONTRACT_DETAIL = """
        select a."PORTFOLIO_ACCOUNT_ID", p."PORTFOLIO_NO", i."INVESTOR_CODE", i."FULL_NAME_EN", i."FULL_NAME_AR", i."NATIONAL_ID", u."UNIT_CODE", u."UNIT_TYPE_CODE", u."BUILDING_NO", u."FLOOR_NO", u."UNIT_NO", a."BOOKING_DATE", a."CONTRACT_DATE", a."CONTRACT_VALUE", a."PAID_VALUE", a."OUTSTANDING_VALUE", round(100 * a."PAID_VALUE" / (nullif(a."CONTRACT_VALUE", 0))::numeric, 2) "PAID_PCT", round(100 * a."OUTSTANDING_VALUE" / (nullif(a."CONTRACT_VALUE", 0))::numeric, 2) "OUTSTANDING_PCT", a."INSTALLMENT_AMOUNT", a."INSTALLMENT_FREQUENCY", a."LAST_PAYMENT_DATE", a."REGULAR_PAYMENT_MONTHS", a."ARREARS_AMOUNT", a."ACCOUNT_STATUS"
        from "MTG_PURCHASED_PORTFOLIO_ACCOUNTS" a
        join "MTG_PURCHASED_PORTFOLIOS" p on p."PORTFOLIO_ID" = a."PORTFOLIO_ID"
        join "MTG_INVESTORS" i on i."INVESTOR_ID" = a."INVESTOR_ID"
        join "MTG_PROJECT_UNITS" u on u."UNIT_ID" = a."UNIT_ID" where (@P731_PORTFOLIO_ID::bigint is null or a."PORTFOLIO_ID" = @P731_PORTFOLIO_ID::bigint) and (@P731_INVESTOR_CODE::text is null or upper(i."INVESTOR_CODE") like concat('%', upper(@P731_INVESTOR_CODE::text), '%')) and (@P731_UNIT_CODE::text is null or upper(u."UNIT_CODE") like concat('%', upper(@P731_UNIT_CODE::text), '%')) and (@P731_ACCOUNT_STATUS::text is null or a."ACCOUNT_STATUS" = @P731_ACCOUNT_STATUS::text) and (coalesce(@P731_ARREARS_ONLY::text, 'N') = 'N' or a."ARREARS_AMOUNT" > 0)
        order by p."PORTFOLIO_NO", i."INVESTOR_CODE", u."UNIT_CODE"
        """;

        public const string P732_INVESTOR_EXPOSURE_CONCENTRATION = """
        select i."INVESTOR_ID", i."INVESTOR_CODE", i."FULL_NAME_EN", i."FULL_NAME_AR", i."NATIONAL_ID", i."DECLARED_INCOME", count(distinct a."PORTFOLIO_ID") "PORTFOLIO_COUNT", count(a."PORTFOLIO_ACCOUNT_ID") "CONTRACT_COUNT", count(distinct a."UNIT_ID") "UNIT_COUNT", sum(a."CONTRACT_VALUE") "TOTAL_CONTRACT_VALUE", sum(a."PAID_VALUE") "TOTAL_PAID_VALUE", sum(a."OUTSTANDING_VALUE") "TOTAL_OUTSTANDING_VALUE", sum(a."ARREARS_AMOUNT") "TOTAL_ARREARS_AMOUNT", round(100 * sum(a."OUTSTANDING_VALUE") / (nullif(sum(sum(a."OUTSTANDING_VALUE")) over (), 0))::numeric, 2) "CONCENTRATION_PCT"
        from "MTG_INVESTORS" i
        join "MTG_PURCHASED_PORTFOLIO_ACCOUNTS" a on a."INVESTOR_ID" = i."INVESTOR_ID"
        join "MTG_PURCHASED_PORTFOLIOS" p on p."PORTFOLIO_ID" = a."PORTFOLIO_ID" where (@P732_DEVELOPER_ID::bigint is null or p."DEVELOPER_ID" = @P732_DEVELOPER_ID::bigint) and (@P732_PROJECT_ID::bigint is null or p."PROJECT_ID" = @P732_PROJECT_ID::bigint) and (@P732_PORTFOLIO_ID::bigint is null or p."PORTFOLIO_ID" = @P732_PORTFOLIO_ID::bigint) and (@P732_INVESTOR_CODE::text is null or upper(i."INVESTOR_CODE") like concat('%', upper(@P732_INVESTOR_CODE::text), '%')) and (@P732_ACTIVE_FLAG::text is null or i."IS_ACTIVE" = (@P732_ACTIVE_FLAG::text = 'Y'))
        group by i."INVESTOR_ID", i."INVESTOR_CODE", i."FULL_NAME_EN", i."FULL_NAME_AR", i."NATIONAL_ID", i."DECLARED_INCOME"
        order by "TOTAL_OUTSTANDING_VALUE" desc
        """;

        public const string P733_UNIT_COLLATERAL_REGISTER = """
        with latest_val as (select v.*, row_number() over (partition by v."PORTFOLIO_ID", v."UNIT_ID"
        order by v."VALUATION_DATE" desc nulls last, v."VALUATION_ID" desc) "RN"
        from "MTG_VALUATIONS" v
        where v."UNIT_ID" is not null), base as (select a."PORTFOLIO_ACCOUNT_ID", p."PORTFOLIO_NO", pr."PROJECT_CODE", u."UNIT_ID", u."UNIT_CODE", u."UNIT_TYPE_CODE", u."BUILDING_NO", u."FLOOR_NO", u."UNIT_NO", u."AREA_SQM", u."LICENSE_STATUS", i."INVESTOR_CODE", i."FULL_NAME_EN" "INVESTOR_NAME_EN", a."CONTRACT_VALUE", a."OUTSTANDING_VALUE", "lv"."VALUATION_DATE", "lv"."MARKET_VALUE", "lv"."RECOMMENDED_VALUE", round(100 * a."OUTSTANDING_VALUE" / (nullif("lv"."RECOMMENDED_VALUE", 0))::numeric, 2) "INDICATIVE_LTV_PCT", round(100 * "lv"."RECOMMENDED_VALUE" / (nullif(a."OUTSTANDING_VALUE", 0))::numeric, 2) "COLLATERAL_COVERAGE_PCT"
        from "MTG_PURCHASED_PORTFOLIO_ACCOUNTS" a
        join "MTG_PURCHASED_PORTFOLIOS" p on p."PORTFOLIO_ID" = a."PORTFOLIO_ID"
        join "MTG_PROJECTS" pr on pr."PROJECT_ID" = p."PROJECT_ID"
        join "MTG_PROJECT_UNITS" u on u."UNIT_ID" = a."UNIT_ID"
        join "MTG_INVESTORS" i on i."INVESTOR_ID" = a."INVESTOR_ID"
        left join latest_val lv on "lv"."PORTFOLIO_ID" = a."PORTFOLIO_ID" and "lv"."UNIT_ID" = a."UNIT_ID" and "lv"."RN" = 1 where (@P733_PORTFOLIO_ID::bigint is null or a."PORTFOLIO_ID" = @P733_PORTFOLIO_ID::bigint) and (@P733_PROJECT_ID::bigint is null or p."PROJECT_ID" = @P733_PROJECT_ID::bigint) and (@P733_UNIT_TYPE_CODE::text is null or u."UNIT_TYPE_CODE" = @P733_UNIT_TYPE_CODE::text) and (@P733_LICENSE_STATUS::text is null or u."LICENSE_STATUS" = @P733_LICENSE_STATUS::text)) select *
        from base where (@P733_MIN_LTV::numeric is null or "INDICATIVE_LTV_PCT" >= @P733_MIN_LTV::numeric)
        order by "INDICATIVE_LTV_PCT" desc nulls last, "PORTFOLIO_NO", "UNIT_CODE"
        """;

        public const string P735_PAYMENT_COLLECTION_DETAIL = """
        select pay."PAYMENT_ID", p."PORTFOLIO_NO", a."PORTFOLIO_ACCOUNT_ID", i."INVESTOR_CODE", i."FULL_NAME_EN", u."UNIT_CODE", pay."DUE_DATE", pay."DUE_AMOUNT", pay."PAYMENT_DATE", pay."PAID_AMOUNT", greatest(pay."DUE_AMOUNT" - coalesce(pay."PAID_AMOUNT", 0), 0) "UNPAID_AMOUNT", pay."PAYMENT_STATUS_CODE", ps."PAYMENT_STATUS_EN", ps."PAYMENT_STATUS_AR", pay."DAYS_LATE", pay."CHEQUE_NO", pay."BANK_NAME"
        from "MTG_ACCOUNT_PAYMENTS" pay
        join "MTG_PURCHASED_PORTFOLIO_ACCOUNTS" a on a."PORTFOLIO_ACCOUNT_ID" = pay."PORTFOLIO_ACCOUNT_ID"
        join "MTG_PURCHASED_PORTFOLIOS" p on p."PORTFOLIO_ID" = a."PORTFOLIO_ID"
        join "MTG_INVESTORS" i on i."INVESTOR_ID" = a."INVESTOR_ID"
        join "MTG_PROJECT_UNITS" u on u."UNIT_ID" = a."UNIT_ID"
        left join "ADM_LKP_PAYMENT_STATUSES" ps on ps."PAYMENT_STATUS_CODE" = pay."PAYMENT_STATUS_CODE" where (@P735_PORTFOLIO_ID::bigint is null or a."PORTFOLIO_ID" = @P735_PORTFOLIO_ID::bigint) and (@P735_DUE_FROM::text is null or pay."DUE_DATE" >= cast(@P735_DUE_FROM::text as date)) and (@P735_DUE_TO::text is null or pay."DUE_DATE" < cast(@P735_DUE_TO::text as date) + 1) and (@P735_PAYMENT_STATUS::text is null or pay."PAYMENT_STATUS_CODE" = @P735_PAYMENT_STATUS::text) and (@P735_INVESTOR_CODE::text is null or upper(i."INVESTOR_CODE") like concat('%', upper(@P735_INVESTOR_CODE::text), '%')) and (coalesce(@P735_LATE_ONLY::text, 'N') = 'N' or coalesce(pay."DAYS_LATE", 0) > 0)
        order by pay."DUE_DATE" desc, p."PORTFOLIO_NO", i."INVESTOR_CODE"
        """;

        public const string P736_ARREARS_AGING_BY_ACCOUNT = """
        with pay_age as (select "PORTFOLIO_ACCOUNT_ID", sum(case when "DUE_DATE" < current_date and coalesce("PAID_AMOUNT", 0) < "DUE_AMOUNT" then "DUE_AMOUNT" - coalesce("PAID_AMOUNT", 0) else 0 end) "PAST_DUE_SCHEDULE_AMOUNT", max(case when "DUE_DATE" < current_date and coalesce("PAID_AMOUNT", 0) < "DUE_AMOUNT" then greatest(coalesce("DAYS_LATE", 0), current_date - "DUE_DATE") else 0 end) "MAX_DPD"
        from "MTG_ACCOUNT_PAYMENTS"
        group by "PORTFOLIO_ACCOUNT_ID"), base as (select a."PORTFOLIO_ACCOUNT_ID", p."PORTFOLIO_NO", i."INVESTOR_CODE", i."FULL_NAME_EN", u."UNIT_CODE", a."OUTSTANDING_VALUE", a."ARREARS_AMOUNT" "RECORDED_ARREARS_AMOUNT", coalesce("pa"."PAST_DUE_SCHEDULE_AMOUNT", 0) "PAST_DUE_SCHEDULE_AMOUNT", coalesce("pa"."MAX_DPD", 0) "MAX_DAYS_PAST_DUE", case when coalesce("pa"."MAX_DPD", 0) = 0 and a."ARREARS_AMOUNT" > 0 then 'ARREARS - DPD UNKNOWN' when coalesce("pa"."MAX_DPD", 0) = 0 then 'CURRENT' when "pa"."MAX_DPD" <= 30 then '1-30' when "pa"."MAX_DPD" <= 60 then '31-60' when "pa"."MAX_DPD" <= 90 then '61-90' when "pa"."MAX_DPD" <= 180 then '91-180' else '180+' end "AGING_BUCKET", a."ACCOUNT_STATUS"
        from "MTG_PURCHASED_PORTFOLIO_ACCOUNTS" a
        join "MTG_PURCHASED_PORTFOLIOS" p on p."PORTFOLIO_ID" = a."PORTFOLIO_ID"
        join "MTG_INVESTORS" i on i."INVESTOR_ID" = a."INVESTOR_ID"
        join "MTG_PROJECT_UNITS" u on u."UNIT_ID" = a."UNIT_ID"
        left join pay_age pa on "pa"."PORTFOLIO_ACCOUNT_ID" = a."PORTFOLIO_ACCOUNT_ID" where (@P736_PORTFOLIO_ID::bigint is null or a."PORTFOLIO_ID" = @P736_PORTFOLIO_ID::bigint) and (@P736_ACCOUNT_STATUS::text is null or a."ACCOUNT_STATUS" = @P736_ACCOUNT_STATUS::text)) select *
        from base where (@P736_BUCKET::text is null or "AGING_BUCKET" = @P736_BUCKET::text) and (@P736_MIN_ARREARS::numeric is null or greatest("RECORDED_ARREARS_AMOUNT", "PAST_DUE_SCHEDULE_AMOUNT") >= @P736_MIN_ARREARS::numeric)
        order by "MAX_DAYS_PAST_DUE" desc, "RECORDED_ARREARS_AMOUNT" desc
        """;

        public const string P737_DOCUMENT_COMPLETENESS_EXPIRY_DETAIL = """
        with base as (select d."DOCUMENT_ID", p."PORTFOLIO_NO", d."ENTITY_TYPE", d."ENTITY_ID", d."DOCUMENT_TYPE_CODE", dt."DOCUMENT_TYPE_NAME" "DOCUMENT_TYPE_NAME_EN", dt."DOCUMENT_TYPE_NAME_AR", dt."IS_MANDATORY", d."DOCUMENT_NO", d."ISSUE_DATE", d."EXPIRY_DATE", d."IS_VERIFIED" AS "VERIFIED_FLAG", d."VERIFIED_BY", d."VERIFIED_AT" AS "VERIFIED_DATE", d."DOCUMENT_STATUS", d."FILE_NAME", case when d."EXPIRY_DATE" is null then 'NO EXPIRY' when d."EXPIRY_DATE" < current_date then 'EXPIRED' when d."EXPIRY_DATE" <= current_date + 30 then 'EXPIRING <=30' else 'VALID' end "EXPIRY_STATUS", case when d."EXPIRY_DATE" is null then null else d."EXPIRY_DATE" - current_date end "DAYS_TO_EXPIRY"
        from "MTG_PURCHASED_PORTFOLIO_DOCUMENTS" d
        join "MTG_PURCHASED_PORTFOLIOS" p on p."PORTFOLIO_ID" = d."PORTFOLIO_ID"
        left join "ADM_LKP_DOCUMENT_TYPES" dt on dt."DOCUMENT_TYPE_CODE" = d."DOCUMENT_TYPE_CODE" where (@P737_PORTFOLIO_ID::bigint is null or d."PORTFOLIO_ID" = @P737_PORTFOLIO_ID::bigint) and (@P737_ENTITY_TYPE::text is null or d."ENTITY_TYPE" = @P737_ENTITY_TYPE::text) and (@P737_DOCUMENT_TYPE::text is null or d."DOCUMENT_TYPE_CODE" = @P737_DOCUMENT_TYPE::text) and (@P737_VERIFIED_FLAG::text is null or d."IS_VERIFIED" = (@P737_VERIFIED_FLAG::text = 'Y'))) select *
        from base where (@P737_EXPIRY_STATUS::text is null or "EXPIRY_STATUS" = @P737_EXPIRY_STATUS::text)
        order by "DAYS_TO_EXPIRY" nulls last, "PORTFOLIO_NO", "DOCUMENT_TYPE_CODE"
        """;

        public const string P738_DUE_DILIGENCE_EXCEPTION_REGISTER = """
        select dd."DD_ID", p."PORTFOLIO_NO", dd."CHECK_TYPE_CODE", ct."CHECK_NAME_EN", ct."CHECK_NAME_AR", ct."IS_MANDATORY" AS "MANDATORY_FLAG", dd."SUBJECT_TYPE", dd."SUBJECT_ID", dd."ASSIGNED_TO", dd."START_DATE", dd."COMPLETION_DATE", dd."RESULT_CODE", dd."RISK_LEVEL_CODE", rl."RISK_LEVEL_NAME_EN", rl."RISK_LEVEL_NAME_AR", dd."IS_EXCEPTION" AS "EXCEPTION_FLAG", substr(dd."FINDINGS", 1, 1000) "FINDINGS", substr(dd."RECOMMENDATION", 1, 1000) "RECOMMENDATION"
        from "MTG_DUE_DILIGENCES" dd
        join "MTG_PURCHASED_PORTFOLIOS" p on p."PORTFOLIO_ID" = dd."PORTFOLIO_ID"
        left join "MTG_LKP_DD_CHECK_TYPES" ct on ct."CHECK_TYPE_CODE" = dd."CHECK_TYPE_CODE"
        left join "ADM_LKP_RISK_LEVELS" rl on rl."RISK_LEVEL_CODE" = dd."RISK_LEVEL_CODE" where (@P738_PORTFOLIO_ID::bigint is null or dd."PORTFOLIO_ID" = @P738_PORTFOLIO_ID::bigint) and (@P738_CHECK_TYPE::text is null or dd."CHECK_TYPE_CODE" = @P738_CHECK_TYPE::text) and (@P738_RISK_LEVEL::text is null or dd."RISK_LEVEL_CODE" = @P738_RISK_LEVEL::text) and (@P738_EXCEPTION_FLAG::text is null or dd."IS_EXCEPTION" = (@P738_EXCEPTION_FLAG::text = 'Y')) and (@P738_ASSIGNED_TO::text is null or upper(dd."ASSIGNED_TO") like concat('%', upper(@P738_ASSIGNED_TO::text), '%')) and (coalesce(@P738_OPEN_ONLY::text, 'N') = 'N' or dd."COMPLETION_DATE" is null)
        order by dd."IS_EXCEPTION" desc, dd."RISK_LEVEL_CODE", dd."START_DATE"
        """;

        public const string P739_INQUIRY_RISK_RESULTS_REGISTER = """
        select q."INQUIRY_ID", p."PORTFOLIO_NO", q."SUBJECT_TYPE", q."SUBJECT_ID", q."INQUIRY_TYPE_CODE", it."INQUIRY_NAME_EN", it."INQUIRY_NAME_AR", q."INQUIRY_DATE", q."REFERENCE_NO", q."RESULT_CODE", q."RISK_LEVEL_CODE", rl."RISK_LEVEL_NAME_EN", rl."RISK_LEVEL_NAME_AR", substr(q."RESULT_DETAILS", 1, 1000) "RESULT_DETAILS"
        from "MTG_INQUIRY_RESULTS" q
        join "MTG_PURCHASED_PORTFOLIOS" p on p."PORTFOLIO_ID" = q."PORTFOLIO_ID"
        left join "MTG_LKP_INQUIRY_TYPES" it on it."INQUIRY_TYPE_CODE" = q."INQUIRY_TYPE_CODE"
        left join "ADM_LKP_RISK_LEVELS" rl on rl."RISK_LEVEL_CODE" = q."RISK_LEVEL_CODE" where (@P739_PORTFOLIO_ID::bigint is null or q."PORTFOLIO_ID" = @P739_PORTFOLIO_ID::bigint) and (@P739_INQUIRY_TYPE::text is null or q."INQUIRY_TYPE_CODE" = @P739_INQUIRY_TYPE::text) and (@P739_RISK_LEVEL::text is null or q."RISK_LEVEL_CODE" = @P739_RISK_LEVEL::text) and (@P739_DATE_FROM::text is null or q."INQUIRY_DATE" >= cast(@P739_DATE_FROM::text as date)) and (@P739_DATE_TO::text is null or q."INQUIRY_DATE" < cast(@P739_DATE_TO::text as date) + 1) and (@P739_SUBJECT_TYPE::text is null or q."SUBJECT_TYPE" = @P739_SUBJECT_TYPE::text)
        order by q."INQUIRY_DATE" desc nulls last, p."PORTFOLIO_NO"
        """;

        public const string P741_LEGAL_REVIEW_EXCEPTIONS_REPORT = """
        with base as (select l."LEGAL_REVIEW_ID", p."PORTFOLIO_ID", p."PORTFOLIO_NO", d."DEVELOPER_ID", d."LEGAL_NAME_EN" "DEVELOPER_NAME_EN", pr."PROJECT_ID", pr."PROJECT_NAME_EN", l."IS_OWNERSHIP_VERIFIED" AS "OWNERSHIP_VERIFIED_FLAG", l."IS_BUILDING_LICENSE_VERIFIED" AS "BUILDING_LICENSE_VERIFIED_FLAG", l."IS_REGISTRATION_POSSIBLE" AS "REGISTRATION_POSSIBLE_FLAG", l."IS_MORTGAGE_POSSIBLE" AS "MORTGAGE_POSSIBLE_FLAG", l."IS_ENCUMBRANCE_FREE" AS "ENCUMBRANCE_FREE_FLAG", l."IS_TITLE_DEED_VERIFIED" AS "TITLE_DEED_VERIFIED_FLAG", (case when not l."IS_OWNERSHIP_VERIFIED" then 1 else 0 end + case when not l."IS_BUILDING_LICENSE_VERIFIED" then 1 else 0 end + case when not l."IS_REGISTRATION_POSSIBLE" then 1 else 0 end + case when not l."IS_MORTGAGE_POSSIBLE" then 1 else 0 end + case when not l."IS_ENCUMBRANCE_FREE" then 1 else 0 end + case when not l."IS_TITLE_DEED_VERIFIED" then 1 else 0 end) "ISSUE_COUNT", rtrim(concat(case when not l."IS_OWNERSHIP_VERIFIED" then 'Ownership; ' end, case when not l."IS_BUILDING_LICENSE_VERIFIED" then 'Building License; ' end, case when not l."IS_REGISTRATION_POSSIBLE" then 'Registration; ' end, case when not l."IS_MORTGAGE_POSSIBLE" then 'Mortgage; ' end, case when not l."IS_ENCUMBRANCE_FREE" then 'Encumbrance; ' end, case when not l."IS_TITLE_DEED_VERIFIED" then 'Title Deed; ' end), '; ') "ISSUE_SUMMARY", substr(l."LEGAL_FINDINGS", 1, 1000) "LEGAL_FINDINGS", substr(l."LEGAL_RECOMMENDATION", 1, 1000) "LEGAL_RECOMMENDATION", l."REVIEWED_BY", l."REVIEW_DATE", l."APPROVED_BY", l."APPROVED_DATE"
        from "MTG_LEGAL_REVIEWS" l
        join "MTG_PURCHASED_PORTFOLIOS" p on p."PORTFOLIO_ID" = l."PORTFOLIO_ID"
        join "MTG_DEVELOPERS" d on d."DEVELOPER_ID" = p."DEVELOPER_ID"
        join "MTG_PROJECTS" pr on pr."PROJECT_ID" = p."PROJECT_ID") select *
        from base where (@P741_PORTFOLIO_ID::bigint is null or "PORTFOLIO_ID" = @P741_PORTFOLIO_ID::bigint) and (@P741_DEVELOPER_ID::bigint is null or "DEVELOPER_ID" = @P741_DEVELOPER_ID::bigint) and (@P741_PROJECT_ID::bigint is null or "PROJECT_ID" = @P741_PROJECT_ID::bigint) and (coalesce(@P741_ONLY_EXCEPTIONS::text, 'Y') = 'N' or "ISSUE_COUNT" > 0) and (coalesce(@P741_APPROVED_ONLY::text, 'N') = 'N' or "APPROVED_DATE" is not null)
        order by "ISSUE_COUNT" desc, "REVIEW_DATE" desc nulls last
        """;

        public const string P742_FINANCIAL_STUDY_ECONOMICS_REPORT = """
        select fs."FIN_STUDY_ID", p."PORTFOLIO_NO", d."LEGAL_NAME_EN" "DEVELOPER_NAME_EN", pr."PROJECT_NAME_EN", p."CURRENCY_CODE", fs."PORTFOLIO_FACE_VALUE", fs."OUTSTANDING_VALUE", fs."PROPOSED_PURCHASE_VALUE", (fs."OUTSTANDING_VALUE" - fs."PROPOSED_PURCHASE_VALUE") "PURCHASE_DISCOUNT_AMOUNT", round(100 * (fs."OUTSTANDING_VALUE" - fs."PROPOSED_PURCHASE_VALUE") / (nullif(fs."OUTSTANDING_VALUE", 0))::numeric, 2) "PURCHASE_DISCOUNT_PCT", fs."TERM_MONTHS", fs."EXPECTED_RETURN_AMOUNT", fs."EXPECTED_RETURN_RATE", fs."ADMIN_EXPENSE_AMOUNT", fs."NET_RETURN_AMOUNT", round(100 * fs."NET_RETURN_AMOUNT" / (nullif(fs."PROPOSED_PURCHASE_VALUE", 0))::numeric, 2) "NET_RETURN_ON_PURCHASE_PCT", fs."CHEQUE_TOTAL_VALUE", fs."CHEQUE_COVERAGE_PCT", fs."DEPOSIT_AMOUNT", fs."DEPOSIT_PCT", fs."PREPARED_BY", fs."PREPARED_DATE", fs."APPROVED_BY", fs."APPROVED_DATE"
        from "MTG_FINANCIAL_STUDIES" fs
        join "MTG_PURCHASED_PORTFOLIOS" p on p."PORTFOLIO_ID" = fs."PORTFOLIO_ID"
        join "MTG_DEVELOPERS" d on d."DEVELOPER_ID" = p."DEVELOPER_ID"
        join "MTG_PROJECTS" pr on pr."PROJECT_ID" = p."PROJECT_ID"
        order by fs."PREPARED_DATE" desc nulls last, p."PORTFOLIO_NO"
        """;

        public const string P743_CHEQUE_MATURITY_COVERAGE_REPORT = """
        select c."CHEQUE_ID", p."PORTFOLIO_NO", c."PORTFOLIO_ACCOUNT_ID", i."INVESTOR_CODE", i."FULL_NAME_EN", c."CHEQUE_NO", c."BANK_NAME", c."CHEQUE_DATE", c."DUE_DATE", c."CHEQUE_AMOUNT", c."IS_ENDORSED_TO_COMPANY" AS "ENDORSED_TO_COMPANY_FLAG", c."CHEQUE_STATUS_CODE", cs."CHEQUE_STATUS_EN", cs."CHEQUE_STATUS_AR", c."CLEARING_DATE", c."RETURN_REASON", a."OUTSTANDING_VALUE" as "ACCOUNT_OUTSTANDING_VALUE", round(100 * c."CHEQUE_AMOUNT" / (nullif(a."OUTSTANDING_VALUE", 0))::numeric, 2) as "ACCOUNT_COVERAGE_PCT", c."DUE_DATE" - current_date as "DAYS_TO_DUE"
        from "MTG_PURCHASED_PORTFOLIO_CHEQUES" c
        join "MTG_PURCHASED_PORTFOLIOS" p on p."PORTFOLIO_ID" = c."PORTFOLIO_ID"
        left join "MTG_PURCHASED_PORTFOLIO_ACCOUNTS" a on a."PORTFOLIO_ACCOUNT_ID" = c."PORTFOLIO_ACCOUNT_ID"
        left join "MTG_INVESTORS" i on i."INVESTOR_ID" = a."INVESTOR_ID"
        left join "ADM_LKP_CHEQUE_STATUSES" cs on cs."CHEQUE_STATUS_CODE" = c."CHEQUE_STATUS_CODE" where (@P743_PORTFOLIO_ID::bigint is null or c."PORTFOLIO_ID" = @P743_PORTFOLIO_ID::bigint) and (@P743_STATUS_CODE::text is null or c."CHEQUE_STATUS_CODE" = @P743_STATUS_CODE::text) and (@P743_DUE_FROM::text is null or c."DUE_DATE" >= to_date(@P743_DUE_FROM::text, 'DD/MM/YYYY')) and (@P743_DUE_TO::text is null or c."DUE_DATE" < to_date(@P743_DUE_TO::text, 'DD/MM/YYYY') + 1) and (@P743_BANK_NAME::text is null or upper(c."BANK_NAME") like concat('%', upper(@P743_BANK_NAME::text), '%')) and (@P743_ENDORSED_FLAG::text is null or c."IS_ENDORSED_TO_COMPANY" = (@P743_ENDORSED_FLAG::text = 'Y'))
        order by c."DUE_DATE", p."PORTFOLIO_NO", c."CHEQUE_NO"
        """;

        public const string P744_PORTFOLIO_PROTECTION_COVERAGE_SUMMARY = """
        with g as (select "PORTFOLIO_ID", count(*) "GUARANTEE_COUNT", sum(coalesce("GUARANTEE_AMOUNT", 0)) "GUARANTEE_AMOUNT", sum(case when "IS_VERIFIED" then 1 else 0 end) "VERIFIED_GUARANTEE_COUNT", sum(case when "EXPIRY_DATE" between current_date and current_date + 30 then 1 else 0 end) "GUARANTEE_EXPIRING_30"
        from "MTG_GUARANTEES"
        group by "PORTFOLIO_ID"), ins as (select "PORTFOLIO_ID", count(*) "INSURANCE_COUNT", sum(coalesce("SUM_INSURED", 0)) "SUM_INSURED", sum(case when "IS_ASSIGNED_TO_COMPANY" then 1 else 0 end) "ASSIGNED_POLICY_COUNT", sum(case when "VALID_TO_DATE" between current_date and current_date + 30 then 1 else 0 end) "INSURANCE_EXPIRING_30"
        from "MTG_INSURANCES"
        group by "PORTFOLIO_ID"), dep as (select "PORTFOLIO_ID", count(*) "DEPOSIT_COUNT", sum(coalesce("DEPOSIT_AMOUNT", 0)) "DEPOSIT_AMOUNT", sum(case when "IS_BLOCKED" then coalesce("DEPOSIT_AMOUNT", 0) else 0 end) "BLOCKED_DEPOSIT_AMOUNT"
        from "MTG_SECURITY_DEPOSITS"
        group by "PORTFOLIO_ID"), base as (select p."PORTFOLIO_ID", p."PORTFOLIO_NO", p."DEVELOPER_ID", p."PROJECT_ID", d."LEGAL_NAME_EN" "DEVELOPER_NAME_EN", pr."PROJECT_NAME_EN", p."PROPOSED_PURCHASE_VALUE", coalesce(g."GUARANTEE_COUNT", 0) "GUARANTEE_COUNT", coalesce(g."GUARANTEE_AMOUNT", 0) "GUARANTEE_AMOUNT", coalesce(g."VERIFIED_GUARANTEE_COUNT", 0) "VERIFIED_GUARANTEE_COUNT", coalesce(g."GUARANTEE_EXPIRING_30", 0) "GUARANTEE_EXPIRING_30", coalesce(ins."INSURANCE_COUNT", 0) "INSURANCE_COUNT", coalesce(ins."SUM_INSURED", 0) "SUM_INSURED", coalesce(ins."ASSIGNED_POLICY_COUNT", 0) "ASSIGNED_POLICY_COUNT", coalesce(ins."INSURANCE_EXPIRING_30", 0) "INSURANCE_EXPIRING_30", coalesce(dep."DEPOSIT_COUNT", 0) "DEPOSIT_COUNT", coalesce(dep."DEPOSIT_AMOUNT", 0) "DEPOSIT_AMOUNT", coalesce(dep."BLOCKED_DEPOSIT_AMOUNT", 0) "BLOCKED_DEPOSIT_AMOUNT", round(100 * coalesce(g."GUARANTEE_AMOUNT", 0) / (nullif(p."PROPOSED_PURCHASE_VALUE", 0))::numeric, 2) "GUARANTEE_COVERAGE_PCT", round(100 * coalesce(dep."DEPOSIT_AMOUNT", 0) / (nullif(p."PROPOSED_PURCHASE_VALUE", 0))::numeric, 2) "DEPOSIT_COVERAGE_PCT"
        from "MTG_PURCHASED_PORTFOLIOS" p
        join "MTG_DEVELOPERS" d on d."DEVELOPER_ID" = p."DEVELOPER_ID"
        join "MTG_PROJECTS" pr on pr."PROJECT_ID" = p."PROJECT_ID"
        left join g on g."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        left join ins on ins."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        left join dep on dep."PORTFOLIO_ID" = p."PORTFOLIO_ID" where (@P744_PORTFOLIO_ID::bigint is null or p."PORTFOLIO_ID" = @P744_PORTFOLIO_ID::bigint) and (@P744_DEVELOPER_ID::bigint is null or p."DEVELOPER_ID" = @P744_DEVELOPER_ID::bigint) and (@P744_PROJECT_ID::bigint is null or p."PROJECT_ID" = @P744_PROJECT_ID::bigint)) select *
        from base where (coalesce(@P744_EXPIRY_RISK_ONLY::text, 'N') = 'N' or "GUARANTEE_EXPIRING_30" > 0 or "INSURANCE_EXPIRING_30" > 0)
        order by "PORTFOLIO_NO"
        """;

        public const string P745_MEMO_VERSION_RECOMMENDATION_REGISTER = """
        select m."MEMO_ID", p."PORTFOLIO_NO", d."LEGAL_NAME_EN" "DEVELOPER_NAME_EN", pr."PROJECT_NAME_EN", m."VERSION_NO", m."MEMO_DATE", m."MEMO_STATUS", m."PREPARED_BY", m."PREPARED_DATE", case when m."VERSION_NO" = max(m."VERSION_NO") over (partition by m."PORTFOLIO_ID") then 'Y' else 'N' end "LATEST_VERSION_FLAG", substr(m."RECOMMENDATION", 1, 1500) "RECOMMENDATION", substr(m."EXECUTIVE_SUMMARY", 1, 1000) "EXECUTIVE_SUMMARY"
        from "MTG_PURCHASED_PORTFOLIO_MEMOS" m
        join "MTG_PURCHASED_PORTFOLIOS" p on p."PORTFOLIO_ID" = m."PORTFOLIO_ID"
        join "MTG_DEVELOPERS" d on d."DEVELOPER_ID" = p."DEVELOPER_ID"
        join "MTG_PROJECTS" pr on pr."PROJECT_ID" = p."PROJECT_ID" where (@P745_PORTFOLIO_ID::bigint is null or m."PORTFOLIO_ID" = @P745_PORTFOLIO_ID::bigint) and (@P745_MEMO_STATUS::text is null or m."MEMO_STATUS" = @P745_MEMO_STATUS::text) and (@P745_DATE_FROM::text is null or m."MEMO_DATE" >= to_date(@P745_DATE_FROM::text, 'DD-MM-YYYY')) and (@P745_DATE_TO::text is null or m."MEMO_DATE" < to_date(@P745_DATE_TO::text, 'DD-MM-YYYY') + 1) and (@P745_PREPARED_BY::text is null or upper(m."PREPARED_BY") like concat('%', upper(@P745_PREPARED_BY::text), '%'))
        order by p."PORTFOLIO_NO", m."VERSION_NO" desc
        """;

        public const string P746_SUBMISSION_READINESS_GAP_ANALYSIS = """
        with "FNV_V_CHEQUE_COVERAGE" AS (
        select pf."PORTFOLIO_ID", pf."PORTFOLIO_NO", pf."OUTSTANDING_VALUE", pf."EXPECTED_RETURN_AMOUNT", pf."OUTSTANDING_VALUE" + pf."EXPECTED_RETURN_AMOUNT" as "REQUIRED_COVERAGE_AMOUNT", coalesce(sum(c."CHEQUE_AMOUNT"), 0) as "CHEQUE_TOTAL_AMOUNT", case when (pf."OUTSTANDING_VALUE" + pf."EXPECTED_RETURN_AMOUNT") = 0 then null else round(coalesce(sum(c."CHEQUE_AMOUNT"), 0) / ((pf."OUTSTANDING_VALUE" + pf."EXPECTED_RETURN_AMOUNT"))::numeric * 100, 2) end as "CHEQUE_COVERAGE_PCT", case when coalesce(sum(c."CHEQUE_AMOUNT"), 0) >= (pf."OUTSTANDING_VALUE" + pf."EXPECTED_RETURN_AMOUNT") then 'Y' else 'N' end as "COVERAGE_OK_FLAG"
        from "MTG_PURCHASED_PORTFOLIOS" pf
        left join "MTG_PURCHASED_PORTFOLIO_CHEQUES" c on c."PORTFOLIO_ID" = pf."PORTFOLIO_ID"
        group by pf."PORTFOLIO_ID", pf."PORTFOLIO_NO", pf."OUTSTANDING_VALUE", pf."EXPECTED_RETURN_AMOUNT"
        ),
        "FNV_V_DOCUMENT_COMPLETENESS" AS (
        with req as (select count(*) "REQUIRED_COUNT"
        from "ADM_LKP_DOCUMENT_TYPES"
        where "IS_MANDATORY" and "IS_ACTIVE"), doc as (select "PORTFOLIO_ID", count(distinct "DOCUMENT_TYPE_CODE") "RECEIVED_REQUIRED_COUNT"
        from "MTG_PURCHASED_PORTFOLIO_DOCUMENTS" d
        where exists (select 1
        from "ADM_LKP_DOCUMENT_TYPES" r
        where r."DOCUMENT_TYPE_CODE" = d."DOCUMENT_TYPE_CODE" and r."IS_MANDATORY" and r."IS_ACTIVE")
        group by "PORTFOLIO_ID") select p."PORTFOLIO_ID", p."PORTFOLIO_NO", r."REQUIRED_COUNT", coalesce(d."RECEIVED_REQUIRED_COUNT", 0) "RECEIVED_REQUIRED_COUNT", greatest(r."REQUIRED_COUNT" - coalesce(d."RECEIVED_REQUIRED_COUNT", 0), 0) "MISSING_REQUIRED_COUNT", case when r."REQUIRED_COUNT" = 0 then 100 else round(coalesce(d."RECEIVED_REQUIRED_COUNT", 0) / (r."REQUIRED_COUNT")::numeric * 100, 2) end "DOCUMENT_COMPLETION_PCT", case when coalesce(d."RECEIVED_REQUIRED_COUNT", 0) >= r."REQUIRED_COUNT" then 'Y' else 'N' end "DOCUMENT_READY_FLAG"
        from "MTG_PURCHASED_PORTFOLIOS" p
        cross join req r
        left join doc d on d."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        ),
        "FNV_V_GUARANTEE_STATUS" AS (
        with req as (select count(*) "REQUIRED_COUNT"
        from "ADM_LKP_GUARANTEE_TYPES"
        where "IS_MANDATORY" and "IS_ACTIVE"), got as (select "PORTFOLIO_ID", count(distinct "GUARANTEE_TYPE_CODE") "VERIFIED_REQUIRED_COUNT"
        from "MTG_GUARANTEES" g
        where "IS_VERIFIED" and exists (select 1
        from "ADM_LKP_GUARANTEE_TYPES" r
        where r."GUARANTEE_TYPE_CODE" = g."GUARANTEE_TYPE_CODE" and r."IS_MANDATORY" and r."IS_ACTIVE")
        group by "PORTFOLIO_ID") select p."PORTFOLIO_ID", p."PORTFOLIO_NO", r."REQUIRED_COUNT", coalesce(g."VERIFIED_REQUIRED_COUNT", 0) "VERIFIED_REQUIRED_COUNT", greatest(r."REQUIRED_COUNT" - coalesce(g."VERIFIED_REQUIRED_COUNT", 0), 0) "MISSING_REQUIRED_COUNT", case when coalesce(g."VERIFIED_REQUIRED_COUNT", 0) >= r."REQUIRED_COUNT" then 'Y' else 'N' end "GUARANTEE_READY_FLAG"
        from "MTG_PURCHASED_PORTFOLIOS" p
        cross join req r
        left join got g on g."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        ),
        "FNV_V_LEGAL_STATUS" AS (
        select p."PORTFOLIO_ID", p."PORTFOLIO_NO", lr."LEGAL_REVIEW_ID", case when lr."IS_OWNERSHIP_VERIFIED" then 'Y' when not lr."IS_OWNERSHIP_VERIFIED" then 'N' end AS "OWNERSHIP_VERIFIED_FLAG", case when lr."IS_BUILDING_LICENSE_VERIFIED" then 'Y' when not lr."IS_BUILDING_LICENSE_VERIFIED" then 'N' end AS "BUILDING_LICENSE_VERIFIED_FLAG", case when lr."IS_REGISTRATION_POSSIBLE" then 'Y' when not lr."IS_REGISTRATION_POSSIBLE" then 'N' end AS "REGISTRATION_POSSIBLE_FLAG", case when lr."IS_MORTGAGE_POSSIBLE" then 'Y' when not lr."IS_MORTGAGE_POSSIBLE" then 'N' end AS "MORTGAGE_POSSIBLE_FLAG", case when lr."IS_ENCUMBRANCE_FREE" then 'Y' when not lr."IS_ENCUMBRANCE_FREE" then 'N' end AS "ENCUMBRANCE_FREE_FLAG", case when lr."IS_TITLE_DEED_VERIFIED" then 'Y' when not lr."IS_TITLE_DEED_VERIFIED" then 'N' end AS "TITLE_DEED_VERIFIED_FLAG", case when lr."LEGAL_REVIEW_ID" is not null and lr."IS_OWNERSHIP_VERIFIED" and lr."IS_BUILDING_LICENSE_VERIFIED" and lr."IS_REGISTRATION_POSSIBLE" and lr."IS_MORTGAGE_POSSIBLE" and lr."IS_ENCUMBRANCE_FREE" and lr."IS_TITLE_DEED_VERIFIED" then 'Y' else 'N' end "LEGAL_READY_FLAG"
        from "MTG_PURCHASED_PORTFOLIOS" p
        left join "MTG_LEGAL_REVIEWS" lr on lr."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        ),
        "FNV_V_PAYMENT_REGULARITY" AS (
        select pa."PORTFOLIO_ACCOUNT_ID", pa."PORTFOLIO_ID", pa."INVESTOR_ID", i."INVESTOR_CODE", i."FULL_NAME_AR", i."FULL_NAME_EN", count(ap."PAYMENT_ID") as "PAYMENT_COUNT", sum(case when ap."PAYMENT_STATUS_CODE" = 'PAID' then 1 else 0 end) as "PAID_COUNT", sum(case when ap."PAYMENT_STATUS_CODE" = 'LATE' then 1 else 0 end) as "LATE_COUNT", sum(case when ap."PAYMENT_STATUS_CODE" in ('PARTIAL', 'UNPAID') then 1 else 0 end) as "PROBLEM_COUNT", max(ap."DAYS_LATE") as "MAX_DAYS_LATE", sum(ap."DUE_AMOUNT") as "TOTAL_DUE", sum(ap."PAID_AMOUNT") as "TOTAL_PAID"
        from "MTG_PURCHASED_PORTFOLIO_ACCOUNTS" pa
        join "MTG_INVESTORS" i on i."INVESTOR_ID" = pa."INVESTOR_ID"
        left join "MTG_ACCOUNT_PAYMENTS" ap on ap."PORTFOLIO_ACCOUNT_ID" = pa."PORTFOLIO_ACCOUNT_ID"
        group by pa."PORTFOLIO_ACCOUNT_ID", pa."PORTFOLIO_ID", pa."INVESTOR_ID", i."INVESTOR_CODE", i."FULL_NAME_AR", i."FULL_NAME_EN"
        ),
        "FNV_V_PORTFOLIO_READINESS" AS (
        with f as (select p."PORTFOLIO_ID", p."PORTFOLIO_NO", case when dc."DOCUMENT_READY_FLAG" = 'Y' then 'Y' else 'N' end "DOCUMENT_READY_FLAG", case when exists (select 1
        from "MTG_DUE_DILIGENCES" dd
        where dd."PORTFOLIO_ID" = p."PORTFOLIO_ID" and dd."IS_EXCEPTION") then 'N' else 'Y' end "DD_READY_FLAG", case when exists (select 1
        from "MTG_VALUATIONS" v
        where v."PORTFOLIO_ID" = p."PORTFOLIO_ID") then 'Y' else 'N' end "VALUATION_READY_FLAG", case when ls."LEGAL_READY_FLAG" = 'Y' then 'Y' else 'N' end "LEGAL_READY_FLAG", case when exists (select 1
        from "MTG_FINANCIAL_STUDIES" fs
        where fs."PORTFOLIO_ID" = p."PORTFOLIO_ID") then 'Y' else 'N' end "FINANCE_READY_FLAG", case when cc."COVERAGE_OK_FLAG" = 'Y' then 'Y' else 'N' end "CHEQUE_READY_FLAG", case when gs."GUARANTEE_READY_FLAG" = 'Y' then 'Y' else 'N' end "GUARANTEE_READY_FLAG", case when exists (select 1
        from "FNV_V_PAYMENT_REGULARITY" pr
        where pr."PORTFOLIO_ID" = p."PORTFOLIO_ID" and (pr."PAYMENT_COUNT" < 12 or pr."PROBLEM_COUNT" > 0)) then 'N' else 'Y' end "PAYMENT_HISTORY_READY_FLAG"
        from "MTG_PURCHASED_PORTFOLIOS" p
        left join "FNV_V_DOCUMENT_COMPLETENESS" dc on dc."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        left join "FNV_V_LEGAL_STATUS" ls on ls."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        left join "FNV_V_CHEQUE_COVERAGE" cc on cc."PORTFOLIO_ID" = p."PORTFOLIO_ID"
        left join "FNV_V_GUARANTEE_STATUS" gs on gs."PORTFOLIO_ID" = p."PORTFOLIO_ID") select f.*, case when "DOCUMENT_READY_FLAG" = 'Y' and "DD_READY_FLAG" = 'Y' and "VALUATION_READY_FLAG" = 'Y' and "LEGAL_READY_FLAG" = 'Y' and "FINANCE_READY_FLAG" = 'Y' and "CHEQUE_READY_FLAG" = 'Y' and "GUARANTEE_READY_FLAG" = 'Y' and "PAYMENT_HISTORY_READY_FLAG" = 'Y' then 'Y' else 'N' end "READY_FOR_SUBMISSION_FLAG"
        from f
        )
        select r."PORTFOLIO_ID", r."PORTFOLIO_NO", d."LEGAL_NAME_EN" as "DEVELOPER_NAME_EN", pr."PROJECT_NAME_EN", r."DOCUMENT_READY_FLAG", r."DD_READY_FLAG", r."PAYMENT_HISTORY_READY_FLAG", r."VALUATION_READY_FLAG", r."LEGAL_READY_FLAG", r."FINANCE_READY_FLAG", r."CHEQUE_READY_FLAG", r."GUARANTEE_READY_FLAG", r."READY_FOR_SUBMISSION_FLAG", (case when r."DOCUMENT_READY_FLAG" = 'N' then 1 else 0 end + case when r."DD_READY_FLAG" = 'N' then 1 else 0 end + case when r."PAYMENT_HISTORY_READY_FLAG" = 'N' then 1 else 0 end + case when r."VALUATION_READY_FLAG" = 'N' then 1 else 0 end + case when r."LEGAL_READY_FLAG" = 'N' then 1 else 0 end + case when r."FINANCE_READY_FLAG" = 'N' then 1 else 0 end + case when r."CHEQUE_READY_FLAG" = 'N' then 1 else 0 end + case when r."GUARANTEE_READY_FLAG" = 'N' then 1 else 0 end) as "FAILED_CHECKS_COUNT", rtrim(concat(case when r."DOCUMENT_READY_FLAG" = 'N' then 'Documents; ' end, case when r."DD_READY_FLAG" = 'N' then 'Due Diligence; ' end, case when r."PAYMENT_HISTORY_READY_FLAG" = 'N' then 'Payment History; ' end, case when r."VALUATION_READY_FLAG" = 'N' then 'Valuation; ' end, case when r."LEGAL_READY_FLAG" = 'N' then 'Legal; ' end, case when r."FINANCE_READY_FLAG" = 'N' then 'Financial; ' end, case when r."CHEQUE_READY_FLAG" = 'N' then 'Cheques; ' end, case when r."GUARANTEE_READY_FLAG" = 'N' then 'Guarantees; ' end), '; ') as "READINESS_GAPS"
        from "FNV_V_PORTFOLIO_READINESS" r
        join "MTG_PURCHASED_PORTFOLIOS" p on p."PORTFOLIO_ID" = r."PORTFOLIO_ID"
        join "MTG_DEVELOPERS" d on d."DEVELOPER_ID" = p."DEVELOPER_ID"
        join "MTG_PROJECTS" pr on pr."PROJECT_ID" = p."PROJECT_ID" where (@P746_DEVELOPER_ID::bigint is null or p."DEVELOPER_ID" = @P746_DEVELOPER_ID::bigint) and (@P746_PROJECT_ID::bigint is null or p."PROJECT_ID" = @P746_PROJECT_ID::bigint) and (@P746_PORTFOLIO_ID::bigint is null or p."PORTFOLIO_ID" = @P746_PORTFOLIO_ID::bigint) and (@P746_READY_FLAG::text is null or r."READY_FOR_SUBMISSION_FLAG" = @P746_READY_FLAG::text)
        order by "FAILED_CHECKS_COUNT" desc, r."PORTFOLIO_NO"
        """;

        public const string P747_APPROVAL_WORKFLOW_DECISION_AUDIT_REPORT = """
        select a."APPROVAL_ID", p."PORTFOLIO_NO", a."SEQUENCE_NO", a."STEP_CODE", s."STEP_NAME_EN", s."STEP_NAME_AR", a."ASSIGNED_TO", a."ASSIGNED_DATE", a."DECISION_CODE", d."DECISION_NAME_EN", d."DECISION_NAME_AR", a."DECISION_DATE", round(coalesce(a."DECISION_DATE", current_date) - a."ASSIGNED_DATE", 2) as "ELAPSED_DAYS", a."RETURN_TO_STEP_CODE", substr(a."COMMENTS", 1, 1000) as "COMMENTS"
        from "MTG_PURCHASED_PORTFOLIO_APPROVALS" a
        join "MTG_PURCHASED_PORTFOLIOS" p on p."PORTFOLIO_ID" = a."PORTFOLIO_ID"
        left join "MTG_LKP_APPROVAL_STEPS" s on s."STEP_CODE" = a."STEP_CODE"
        left join "ADM_LKP_DECISION_TYPES" d on d."DECISION_CODE" = a."DECISION_CODE" where (@P747_PORTFOLIO_ID::bigint is null or a."PORTFOLIO_ID" = @P747_PORTFOLIO_ID::bigint) and (@P747_STEP_CODE::text is null or a."STEP_CODE" = @P747_STEP_CODE::text) and (@P747_DECISION_CODE::text is null or a."DECISION_CODE" = @P747_DECISION_CODE::text) and (@P747_ASSIGNED_TO::text is null or upper(a."ASSIGNED_TO") like concat('%', upper(@P747_ASSIGNED_TO::text), '%')) and (@P747_DATE_FROM::text is null or a."ASSIGNED_DATE" >= to_date(@P747_DATE_FROM::text, 'DD-MM-YYYY')) and (@P747_DATE_TO::text is null or a."ASSIGNED_DATE" < to_date(@P747_DATE_TO::text, 'DD-MM-YYYY') + 1) and (coalesce(@P747_PENDING_ONLY::text, 'N') = 'N' or a."DECISION_DATE" is null)
        order by p."PORTFOLIO_NO", a."SEQUENCE_NO", a."APPROVAL_ID"
        """;

        public const string P748_STATUS_MOVEMENT_PIPELINE_HISTORY_REPORT = """
        -- Oracle: cast(timestamp as date) keeps the time, so days in status has fractions; PostgreSQL ::date would drop them.
        with h as (select sh.*, lead(sh."CHANGE_AT") over (partition by sh."PORTFOLIO_ID"
        order by sh."CHANGE_AT", sh."STATUS_HIST_ID") "NEXT_CHANGE_DATE"
        from "MTG_PURCHASED_PORTFOLIO_STATUS_HIST" sh) select h."STATUS_HIST_ID", p."PORTFOLIO_NO", h."FROM_STATUS", fs."STATUS_NAME_EN" "FROM_STATUS_NAME_EN", fs."STATUS_NAME_AR" "FROM_STATUS_NAME_AR", h."TO_STATUS", ts."STATUS_NAME_EN" "TO_STATUS_NAME_EN", ts."STATUS_NAME_AR" "TO_STATUS_NAME_AR", h."CHANGE_AT" AS "CHANGE_DATE", h."NEXT_CHANGE_DATE", round((extract(epoch from coalesce(h."NEXT_CHANGE_DATE", now()) - h."CHANGE_AT") / 86400)::numeric, 2) "DAYS_IN_STATUS", h."CHANGED_BY", h."COMMENTS"
        from h
        join "MTG_PURCHASED_PORTFOLIOS" p on p."PORTFOLIO_ID" = h."PORTFOLIO_ID"
        left join "MTG_LKP_PORTFOLIO_STATUSES" fs on fs."STATUS_CODE" = h."FROM_STATUS"
        left join "MTG_LKP_PORTFOLIO_STATUSES" ts on ts."STATUS_CODE" = h."TO_STATUS" where (@P748_PORTFOLIO_ID::bigint is null or h."PORTFOLIO_ID" = @P748_PORTFOLIO_ID::bigint) and (@P748_FROM_STATUS::text is null or h."FROM_STATUS" = @P748_FROM_STATUS::text) and (@P748_TO_STATUS::text is null or h."TO_STATUS" = @P748_TO_STATUS::text) and (@P748_DATE_FROM::text is null or h."CHANGE_AT" >= cast(to_date(@P748_DATE_FROM::text, 'DD-MM-YYYY') as timestamp)) and (@P748_DATE_TO::text is null or h."CHANGE_AT" < cast(to_date(@P748_DATE_TO::text, 'DD-MM-YYYY') + 1 as timestamp)) and (@P748_CHANGED_BY::text is null or upper(h."CHANGED_BY") like concat('%', upper(@P748_CHANGED_BY::text), '%'))
        order by p."PORTFOLIO_NO", h."CHANGE_AT"
        """;

        public const string P749_ACQUISITION_SETTLEMENT_ACCOUNTING_READINESS_REGISTER_REPORT = """
        select s."SETTLEMENT_ID", p."PORTFOLIO_NO", d."LEGAL_NAME_EN" "DEVELOPER_NAME_EN", pr."PROJECT_NAME_EN", s."CONTRACT_EXECUTION_DATE", s."CUT_OFF_DATE", s."ACQUISITION_DATE", s."SETTLEMENT_DATE", s."ACCOUNTING_DATE", s."CURRENCY_CODE", s."APPROVED_PURCHASE_VALUE", s."PAYMENT_AMOUNT", (coalesce(s."PAYMENT_AMOUNT", 0) - s."APPROVED_PURCHASE_VALUE") "PAYMENT_VARIANCE", s."ACQUISITION_COST_AMOUNT", s."PAYMENT_METHOD_CODE", pm."PAYMENT_METHOD_NAME_EN", pm."PAYMENT_METHOD_NAME_AR", s."BANK_GL_ACCOUNT_CODE", s."BANK_NAME", s."BANK_ACCOUNT_NO", s."TRANSFER_REFERENCE", s."CHEQUE_NO", s."CHEQUE_DATE", s."SELLER_PAYMENT_REFERENCE", s."SETTLEMENT_STATUS_CODE", s."ACCOUNTING_STATUS_CODE", s."GL_BATCH_REFERENCE", s."GL_JOURNAL_REFERENCE", s."SETTLED_BY", s."SETTLED_ON_AT" AS "SETTLED_ON"
        from "MTG_PURCHASED_PORTFOLIO_SETTLEMENTS" s
        join "MTG_PURCHASED_PORTFOLIOS" p on p."PORTFOLIO_ID" = s."PORTFOLIO_ID"
        join "MTG_DEVELOPERS" d on d."DEVELOPER_ID" = p."DEVELOPER_ID"
        join "MTG_PROJECTS" pr on pr."PROJECT_ID" = p."PROJECT_ID"
        left join "MTG_LKP_PORTFOLIO_PAYMENT_METHODS" pm on pm."PAYMENT_METHOD_CODE" = s."PAYMENT_METHOD_CODE" where (@P749_PORTFOLIO_ID::bigint is null or s."PORTFOLIO_ID" = @P749_PORTFOLIO_ID::bigint) and (@P749_SETTLEMENT_STATUS::text is null or s."SETTLEMENT_STATUS_CODE" = @P749_SETTLEMENT_STATUS::text) and (@P749_ACCOUNTING_STATUS::text is null or s."ACCOUNTING_STATUS_CODE" = @P749_ACCOUNTING_STATUS::text) and (@P749_PAYMENT_METHOD::text is null or s."PAYMENT_METHOD_CODE" = @P749_PAYMENT_METHOD::text) and (@P749_DATE_FROM::text is null or s."SETTLEMENT_DATE" >= cast(to_date(@P749_DATE_FROM::text, 'DD-MM-YYYY') as timestamp)) and (@P749_DATE_TO::text is null or s."SETTLEMENT_DATE" < cast(to_date(@P749_DATE_TO::text, 'DD-MM-YYYY') + 1 as timestamp)) and (@P749_BANK_GL::text is null or upper(s."BANK_GL_ACCOUNT_CODE") like concat('%', upper(@P749_BANK_GL::text), '%'))
        order by s."SETTLEMENT_DATE" desc nulls last, p."PORTFOLIO_NO"
        """;
    }
}
